/* Koncepcje modeli – dane wspólne dla strony Koncepcje modeli i Mapy banku (widok próba). */
window.RT_KON={"dom":[["K1","Ryzyko kredytowe – parametry","PD, LGD, EAD, ECL","#bf8165"],["K2","Ryzyko kredytowe – portfel","rozkład strat, kapitał","#a8694c"],["R","Ryzyko rynkowe","VaR, ES, zmienność","#6f7f58"],["O","Ryzyko operacyjne","straty operacyjne, prawne","#8a6c90"],["L","Płynność","finansowanie, odpływy","#5f8aa6"],["C","Kapitał ekonomiczny","agregacja, alokacja","#a6824c"],["S","Stres testy","scenariusze skrajne","#5c564d"],["M","Ryzyko modeli","inwentarz, istotność, pomiar","#9a9176"]],"c":[{"id":"score","d":"K1","g":"PD","n":"Scoring i karty punktowe","o":"regresja logistyczna, WoE / IV","k":"EL","s":"Ocena punktowa klienta z cech wniosku i historii zachowania. Zmienne grupowane i kodowane wagą dowodu (WoE), selekcja według wartości informacyjnej (IV).","idea":"logit(PD) = β₀ + Σ βᵢ · WoEᵢ","use":"Decyzja kredytowa, cut-off, wejście do PD w IRB i ECL.","u":5,"reg":"","old":"","ot":"Ranking / PD","otc":"#2f6f8f","det":{"p":["Scoring zamienia cechy klienta na jedną liczbę – liczbę punktów – która porządkuje klientów od najbezpieczniejszych do najbardziej ryzykownych. Najczęściej pod spodem jest regresja logistyczna: model szacuje logarytm szansy, że klient spłaci kredyt, jako sumę wpływów poszczególnych cech.","Zmienne ciągłe (wiek, dochód, wskaźnik zadłużenia) dzieli się na przedziały, a każdy przedział koduje się wagą dowodu (WoE) – logarytmem stosunku udziału dobrych do złych klientów w przedziale. Dzięki temu zależność staje się monotoniczna i łatwa do wytłumaczenia. Wartość informacyjna (IV) pomaga wybrać zmienne, które naprawdę różnicują klientów.","Na koniec wynik przelicza się na punkty: ustala się punkt odniesienia (np. 600 punktów = szansa 50:1) i liczbę punktów podwajającą szansę (PDO, np. 20). Karta punktowa jest czytelna dla biznesu i audytu – każdy przedział cechy ma swoje punkty. Scoring decyduje o akceptacji wniosku, a po kalibracji daje PD do IRB i ECL."],"ex":["Od punktów do PD",["Skala: 600 pkt = szansa 50:1, PDO = 20 (każde +20 pkt podwaja szansę).","Klient A ma 620 pkt → szansa 100:1 → PD = 1 / 101 ≈ 1,0%.","Klient B ma 580 pkt → szansa 25:1 → PD = 1 / 26 ≈ 3,8%.","Różnica 40 punktów oznacza prawie czterokrotnie wyższe ryzyko."]]},"par":[["β","współczynniki zmiennych (wagi cech)","Regresja logistyczna metodą największej wiarygodności na historii dobrych i złych klientów; zmienne zwykle zakodowane WoE."]]},{"id":"rating","d":"K1","g":"PD","n":"Modele ratingowe","o":"eksperckie, statystyczne, hybrydowe","k":"EL","s":"Przypisanie klasy ryzyka (ratingu) z oceny finansowej i jakościowej; skala główna (master scale) przekłada klasy na PD.","idea":"klasa ratingowa → PD z kalibracji na długim okresie","use":"Klienci korporacyjni, banki, JST; IRB, limity, ceny.","u":5,"reg":"","old":"","ot":"Ranking / PD","otc":"#2f6f8f","det":{"p":["Model ratingowy przypisuje klientowi klasę ryzyka – podobnie jak agencje ratingowe (AAA, BBB…), ale w skali wewnętrznej banku. Stosuje się go tam, gdzie klientów jest mniej, a każdy jest inny: przedsiębiorstwa, banki, samorządy.","Typowo łączy dwie części. Część ilościowa ocenia sprawozdania: rentowność, zadłużenie, płynność, pokrycie odsetek. Część jakościowa ocenia to, czego nie ma w liczbach: pozycję rynkową, jakość zarządu, strukturę właścicielską, ryzyko branży. Do tego dochodzą sygnały ostrzegawcze i korekty (np. wsparcie grupy kapitałowej), które mogą podnieść lub obniżyć klasę.","Ostatni krok to skala główna (master scale): każda klasa ma przypisane PD skalibrowane na długim okresie, obejmującym cały cykl koniunkturalny. Dzięki jednej skali klasy z różnych modeli (korporacje, MŚP, banki) są porównywalne – na tej skali opiera się limitowanie, cena kredytu i wymóg kapitałowy."],"ex":["Ocena spółki produkcyjnej",["Ocena finansowa (rentowność, zadłużenie, płynność) daje klasę 6.","Ocena jakościowa: silna pozycja rynkowa, doświadczony zarząd → +1 klasa.","Sygnał ostrzegawczy: opóźnienia wobec ZUS → −1 klasa (z powrotem 6).","Na skali głównej klasa 6 = PD 1,2% – tego PD użyje bank w cenie i kapitale."]]},"par":[["PDₖ","PD przypisane klasom ratingowym","Kalibracja skali głównej na długookresowej częstości defaultów w klasach."],["w","wagi części finansowej i jakościowej","Statystycznie albo ekspercko, z kontrolą mocy dyskryminacyjnej."]]},{"id":"merton","d":"K1","g":"PD","n":"Model Mertona","o":"Merton, 1974","k":"EL","s":"Default następuje, gdy wartość aktywów spadnie poniżej długu. Kapitał własny to opcja kupna na aktywa firmy.","idea":"PD = N(−DD), DD = [ln(V/D) + (μ − σ²/2)T] / (σ√T)","use":"Fundament modeli strukturalnych i wzoru IRB.","u":2,"reg":"","old":"","ot":"Ranking / PD","otc":"#2f6f8f","det":{"p":["Robert Merton zaproponował w 1974 roku prostą i bardzo wpływową ideę: firma bankrutuje, gdy wartość jej aktywów spadnie poniżej wartości długu w terminie spłaty. Właściciele mają wtedy coś jak opcję kupna na aktywa firmy – jeśli aktywa są warte więcej niż dług, spłacają go i zatrzymują nadwyżkę; jeśli mniej, oddają firmę wierzycielom.","Kluczowa miara to odległość do niewypłacalności (DD): o ile odchyleń standardowych wartość aktywów jest powyżej długu. Im większy bufor i im mniejsza zmienność aktywów, tym niższe PD. Wartości i zmienności aktywów nie widać bezpośrednio – wyznacza się je z ceny akcji i jej zmienności, korzystając z wzorów na wycenę opcji.","Model Mertona jest fundamentem całej rodziny modeli strukturalnych: KMV, CreditMetrics, a także wzoru IRB w Bazylei, który zakłada, że wartość aktywów dłużnika zależy od wspólnego czynnika gospodarki."],"ex":["Bufor nad długiem",["Aktywa V = 100, dług D = 60, zmienność aktywów σ = 20%, wzrost μ = 5%, horyzont 1 rok.","DD = [ln(100/60) + (0,05 − 0,02)] / 0,20 = (0,511 + 0,03) / 0,20 ≈ 2,70.","PD = N(−2,70) ≈ 0,35%.","Gdy aktywa spadną do 80: DD ≈ 1,59, PD ≈ 5,6% – ryzyko rośnie szybciej niż spadek wartości."]]},"par":[["V","wartość aktywów firmy","Nieobserwowalna – wyznaczana z kapitalizacji rynkowej przez równanie wyceny opcji."],["σᵥ","zmienność aktywów","Wyznaczana razem z V z zmienności kursu akcji (układ dwóch równań)."]]},{"id":"surv","d":"K1","g":"PD","n":"Modele przeżycia","o":"Cox 1972, hazard dyskretny","k":"EL","s":"Modelują czas do defaultu i funkcję hazardu; pozwalają liczyć PD w dowolnym horyzoncie.","idea":"h(t|x) = h₀(t) · exp(β′x)","use":"PD lifetime w MSSF 9, modele przedpłat.","u":3,"reg":"","old":"","ot":"Krzywa lifetime","otc":"#b5679a","det":{"p":["Analiza przeżycia przyszła do ryzyka kredytowego z medycyny. Zamiast pytać „czy klient zbankrutuje w ciągu roku”, pyta „kiedy” – modeluje czas do defaultu. Kluczowa jest funkcja hazardu: prawdopodobieństwo defaultu w krótkim okresie pod warunkiem, że klient dotąd spłacał.","Model proporcjonalnych hazardów Coxa rozdziela hazard na dwie części: hazard bazowy (jak ryzyko zmienia się z wiekiem kredytu – np. rośnie w pierwszych latach, potem spada) i mnożnik zależny od cech klienta. Wersje dyskretne (hazard w miesiącach lub latach) estymuje się zwykłą regresją logistyczną na danych panelowych.","Wielka zaleta: model naturalnie obsługuje kredyty, które jeszcze trwają (obserwacje ucięte), i od razu daje PD w każdym horyzoncie. Dlatego jest jednym z głównych narzędzi do PD lifetime w MSSF 9 i do modeli przedpłat."],"ex":["Hazard i PD w 3 lata",["Hazard bazowy: 1% rocznie. Klient ma cechy podnoszące hazard: exp(β′x) = 2.","Jego hazard: 2% rocznie.","Przeżycie 3 lat: exp(−0,02 × 3) = 0,942.","PD 3-letnie = 1 − 0,942 ≈ 5,8% (a nie 3 × 2% = 6% – bo defaultować można tylko raz)."]]},"par":[["β","współczynniki hazardu","Metoda częściowej wiarygodności Coxa, z obserwacjami uciętymi."],["h₀(t)","hazard bazowy","Nieparametrycznie (estymator Breslowa) albo parametrycznie (np. Weibull)."]]},{"id":"migr","d":"K1","g":"PD","n":"Macierze migracji","o":"łańcuchy Markowa","k":"EL","s":"Prawdopodobieństwa przejść między klasami ratingowymi w roku; podejście kohortowe albo czasu ciągłego (generator).","idea":"P(t) = Pᵗ  lub  P(t) = exp(Q·t)","use":"PD lifetime, CreditMetrics, stres migracji.","u":4,"reg":"","old":"","ot":"Krzywa lifetime","otc":"#b5679a","det":{"p":["Macierz migracji pokazuje, jak klienci przemieszczają się między klasami ratingowymi w ciągu roku: ilu zostaje w swojej klasie, ilu się poprawia, ilu pogarsza, a ilu trafia do defaultu. Ostatnia kolumna macierzy to właśnie roczne PD dla każdej klasy.","Jeśli założyć, że przejścia zależą tylko od bieżącej klasy (łańcuch Markowa), to macierz na kilka lat dostaje się, mnożąc roczną macierz przez siebie. Tak powstają krzywe PD lifetime: klient z dobrą klasą rzadko defaultuje od razu, ale może najpierw spaść do słabszej klasy, a potem dopiero do defaultu.","Macierz estymuje się metodą kohortową (kto był w klasie na początku roku, gdzie był na końcu) albo w czasie ciągłym, z generatora, co lepiej wykorzystuje dane. Migracje są sercem CreditMetrics i stres testów, w których macierz „przesuwa się” w dół w dekoniunkturze."],"ex":["Dwa lata zamiast jednego",["Klasa A: 90% zostaje, 8% spada do B, 2% default. Klasa B: 10% wraca do A, 80% zostaje, 10% default.","PD roczne klienta z A = 2%.","PD dwuletnie = 2% + 90% × 2% + 8% × 10% = 2% + 1,8% + 0,8% = 4,6%.","Ścieżka „A → B → default” dokłada 0,8 pp – tego nie widać w samym PD rocznym."]]},"par":[["pᵢⱼ","prawdopodobieństwa przejść między klasami","Częstości w kohortach (MLE) albo z generatora w czasie ciągłym."]]},{"id":"lgdw","d":"K1","g":"LGD","n":"Workout LGD","o":"odzyski z windykacji","k":"EL","s":"Strata liczona z historycznych odzysków i kosztów windykacji, zdyskontowanych do daty defaultu.","idea":"LGD = 1 − Σ (odzyski − koszty)·DF / EAD","use":"LGD w IRB i MSSF 9.","u":5,"reg":"","old":"","ot":"Parametr","otc":"#7a8b3a","det":{"p":["Workout LGD to najbardziej bezpośredni sposób liczenia straty: bank patrzy na kredyty, które już zdefaultowały, i sprawdza, ile udało się odzyskać i ile to kosztowało. Strata to część ekspozycji, której nie odzyskano, po uwzględnieniu wartości pieniądza w czasie.","Odzyski przychodzą z różnych źródeł: spłaty po restrukturyzacji, sprzedaż zabezpieczenia, egzekucja, sprzedaż wierzytelności. Wszystkie przepływy dyskontuje się do daty defaultu stopą odzwierciedlającą ryzyko odzysku. Koszty windykacji (prawne, zewnętrzne firmy, wewnętrzne) obniżają odzysk.","Trudności są praktyczne: proces odzysku trwa latami, więc w danych jest wiele spraw niezakończonych; trzeba zdecydować, jak je potraktować. Do tego dochodzą klienci, którzy wyzdrowieli (wrócili do spłaty) – ich strata jest bliska zeru, co prowadzi do modeli dwuetapowych."],"ex":["Strata z jednej sprawy",["EAD w dniu defaultu: 100 tys. zł.","Po 2 latach sprzedaż zabezpieczenia: 50 tys. zł, koszty windykacji: 5 tys. zł.","Wartość bieżąca odzysku przy stopie 8%: 45 / 1,08² ≈ 38,6 tys. zł.","LGD = 1 − 38,6 / 100 ≈ 61%."]]},"par":[["LGD","strata w razie defaultu","Średnia zdyskontowanych strat na sprawach zakończonych; kluczowe są stopa dyskontowa, koszty i traktowanie spraw otwartych."]]},{"id":"lgd2","d":"K1","g":"LGD","n":"LGD dwuetapowe","o":"cure rate × strata","k":"EL","s":"Najpierw prawdopodobieństwo wyzdrowienia (powrotu do spłaty), potem strata dla niewyzdrowionych; regresja beta lub ułamkowa.","idea":"LGD = (1 − p_cure) · LGD_loss","use":"Detal, hipoteki, MSSF 9.","u":4,"reg":"","old":"","ot":"Parametr","otc":"#7a8b3a","det":{"p":["Wielu klientów, którzy formalnie wpadli w default, potem wraca do regularnej spłaty – „wyzdrowieje”. Ich strata jest niemal zerowa. Inni przechodzą do windykacji i tam strata bywa duża. Jeden model LGD dla wszystkich miesza dwie bardzo różne populacje i ma rozkład w kształcie litery U.","Model dwuetapowy rozdziela problem. Najpierw szacuje prawdopodobieństwo wyzdrowienia (cure rate) – zwykle regresją logistyczną na cechach klienta, zabezpieczenia i długości opóźnienia. Potem osobno szacuje stratę dla tych, którzy nie wyzdrowieli – regresją beta, ułamkową albo na podstawie wartości zabezpieczenia (LTV).","Takie modele są dokładniejsze i lepiej się tłumaczą: widać, czy zmiana LGD wynika z gorszej skuteczności restrukturyzacji, czy ze spadku cen zabezpieczeń. Są standardem w portfelach detalicznych i hipotecznych."],"ex":["Wyzdrowienie zmienia wszystko",["Prawdopodobieństwo wyzdrowienia: 60%.","Strata dla niewyzdrowionych (windykacja zabezpieczenia): 45%.","LGD = (1 − 0,60) × 45% = 18%.","Jeśli cure rate spadnie do 40%: LGD = 0,6 × 45% = 27% – wzrost o połowę."]]},"par":[["p꜀","prawdopodobieństwo wyzdrowienia (cure rate)","Regresja logistyczna na sprawach zakończonych."],["LGDₗ","strata dla niewyzdrowionych","Regresja beta lub ułamkowa, często z LTV jako główną zmienną."]]},{"id":"lgdd","d":"K1","g":"LGD","n":"LGD downturn","o":"dekoniunktura","k":"UL","s":"LGD odpowiadające okresowi spowolnienia gospodarczego; wymagane w metodzie IRB.","idea":"LGD_DT ≥ LGD długookresowe (wytyczne EBA)","use":"Wzór IRB, RWA.","u":3,"reg":"CRR art. 181; rozporządzenie delegowane (UE) 2021/930; wytyczne EBA/GL/2019/03 (LGD downturn)","old":"","ot":"Parametr","otc":"#7a8b3a","det":{"p":["Straty w razie defaultu nie są stałe w cyklu: w recesji spadają ceny nieruchomości i innych zabezpieczeń, rynki wtórne wierzytelności wysychają, a windykacja trwa dłużej. Dlatego regulacje wymagają, by w metodzie IRB LGD odzwierciedlało warunki dekoniunktury.","Wytyczne EBA opisują, jak to zrobić: zidentyfikować okres spowolnienia (na podstawie PKB, bezrobocia, cen nieruchomości), sprawdzić, jakie LGD obserwowano w tym okresie, a jeśli danych brakuje – oszacować wpływ dekoniunktury z modelu lub z zależności LGD od czynników makro. LGD downturn nie może być niższe niż średnie długookresowe.","Wybór tej wartości bezpośrednio wpływa na kapitał: we wzorze IRB wymóg jest proporcjonalny do LGD, więc wzrost LGD z 25% do 32% podnosi RWA o ponad jedną czwartą."],"ex":["Kapitał rośnie razem z LGD",["Średnie LGD długookresowe portfela hipotecznego: 25%.","W latach spowolnienia obserwowano LGD 32% → LGD downturn = 32%.","RWA w IRB jest proporcjonalne do LGD: 32 / 25 = 1,28.","Wymóg kapitałowy dla portfela rośnie o 28%."]]},"par":[["LGDᴰᵀ","LGD w dekoniunkturze","Z okresu spowolnienia albo z modelu zależności LGD od makro; plus marża ostrożności."]]},{"id":"lgdid","d":"K1","g":"LGD","n":"LGD in default i ELBE","o":"ekspozycje w defaulcie","k":"UL","s":"Dla ekspozycji już w defaulcie: najlepsze oszacowanie straty (ELBE) i LGD in default z narzutem na możliwe dodatkowe straty w okresie odzysku.","idea":"K = max(0, LGD in default − ELBE)","use":"IRB dla ekspozycji w defaulcie, kapitał wewnętrzny portfela NPL.","u":3,"reg":"CRR art. 181; wytyczne EBA/GL/2017/16, rozdz. 7 (ekspozycje w defaulcie: ELBE, LGD in default)","old":"","ot":"Parametr","otc":"#7a8b3a","det":{"p":["Kiedy kredyt jest już w defaulcie, bank nadal go posiada – i nadal ponosi ryzyko, że odzyska mniej, niż zakłada. Dla takich ekspozycji metoda IRB wymaga dwóch oszacowań zamiast jednego LGD.","ELBE (expected loss best estimate) to najlepsze oszacowanie straty na dziś: uwzględnia czas w defaulcie, dotychczasowe odzyski, stan zabezpieczenia i bieżące warunki gospodarcze; porównuje się je z utworzonymi odpisami. LGD in default to ELBE powiększone o narzut na możliwe dodatkowe straty nieoczekiwane w pozostałym okresie odzysku (z uwzględnieniem dekoniunktury). Oba parametry szacuje się zwykle w podziale według czasu w defaulcie – im dłużej trwa windykacja, tym zwykle wyższa oczekiwana strata.","Wymóg kapitałowy dla ekspozycji w defaulcie to różnica między LGD in default a ELBE. Tę samą logikę banki stosują w kapitale wewnętrznym (ICAAP) dla portfeli NPL – kapitał na niepewność przyszłych odzysków ponad odpisy."],"ex":["Kredyt dwa lata w windykacji",["EAD = 100 tys. zł; po 2 latach w defaulcie ELBE = 45%, odpis = 45 tys. zł.","LGD in default (z narzutem na niepewność odzysku) = 55%.","K = 55% − 45% = 10% → RWA = 12,5 × 10% × 100 = 125 tys. zł.","Kapitał: 8% × 125 = 10 tys. zł na możliwą dodatkową stratę."]]},"par":[["ELBE","najlepsze oszacowanie straty","Według czasu w defaulcie, z historii odzysków."],["LGDᴵᴰ","LGD in default","ELBE powiększone o narzut na niepewność odzysku w dekoniunkturze."]]},{"id":"ccf","d":"K1","g":"EAD","n":"CCF i wykorzystanie limitu","o":"współczynnik konwersji","k":"EL","s":"Jaka część niewykorzystanego limitu zostanie pobrana przed defaultem.","idea":"EAD = wykorzystanie + CCF × (limit − wykorzystanie)","use":"Karty, linie, gwarancje; IRB i ECL.","u":4,"reg":"","old":"","ot":"Parametr","otc":"#7a8b3a","det":{"p":["Ekspozycja w chwili defaultu (EAD) to nie tylko to, co klient już pobrał. Klienci z limitami – kartą, linią kredytową, debetem – w trudnej sytuacji zwykle wykorzystują wolne środki, zanim przestaną płacić. CCF (współczynnik konwersji kredytowej) mówi, jaka część niewykorzystanego limitu zostanie pobrana do momentu defaultu.","CCF szacuje się na kredytach, które zdefaultowały: porównuje się wykorzystanie i limit rok przed defaultem z ekspozycją w dniu defaultu. Wynik zależy od typu produktu, poziomu wykorzystania (klient wykorzystujący 95% ma mało miejsca na wzrost), zachowania klienta i reakcji banku (obniżanie limitów).","Ten sam parametr działa w IRB i w ECL; dla gwarancji i akredytyw określa, jaka część zobowiązania pozabilansowego zamieni się w ekspozycję bilansową."],"ex":["Karta kredytowa przed defaultem",["Limit: 10 tys. zł, wykorzystanie dziś: 4 tys. zł, wolne: 6 tys. zł.","CCF z danych historycznych: 60%.","EAD = 4 + 0,6 × 6 = 7,6 tys. zł.","Liczenie straty od 4 tys. zaniżyłoby EAD prawie o połowę."]]},"par":[["CCF","współczynnik konwersji kredytowej","Z defaultów: przyrost ekspozycji do dnia defaultu podzielony przez wolny limit rok wcześniej."]]},{"id":"ecl","d":"K1","g":"ECL · MSSF 9","n":"Oczekiwana strata (ECL)","o":"MSSF 9, 2018","k":"EL","s":"Odpis na oczekiwane straty kredytowe: 12-miesięczny w koszyku 1, lifetime w koszykach 2 i 3, z uwzględnieniem prognoz makro.","idea":"ECL = Σₜ PDₜ · LGDₜ · EADₜ · DFₜ","use":"Odpisy w bilansie, koszt ryzyka w RZiS.","u":5,"reg":"MSSF 9, rozdz. 5.5 (utrata wartości); Rekomendacja R KNF","old":"","ot":"Wzór / agregacja","otc":"#4b4740","det":{"p":["ECL (Expected Credit Loss) to odpis, który bank tworzy na oczekiwane straty kredytowe zgodnie z MSSF 9. W odróżnieniu od dawnego MSR 39 nie czeka się na zdarzenie straty – odpis tworzy się od pierwszego dnia, a jego wysokość zależy od tego, jak bardzo pogorszyła się jakość kredytu.","Kluczowy jest podział na koszyki: w koszyku 1 (bez istotnego wzrostu ryzyka) liczy się stratę z defaultów w najbliższych 12 miesiącach; w koszyku 2 (istotny wzrost ryzyka) i 3 (default) – stratę z całego życia kredytu. ECL to suma po okresach: prawdopodobieństwo defaultu w danym okresie × strata × ekspozycja, zdyskontowana efektywną stopą procentową.","Parametry muszą być „punktowe” (point-in-time) i uwzględniać prognozy makro z kilku scenariuszy. ECL trafia do bilansu jako odpis, a jego zmiana – do rachunku wyników jako koszt ryzyka."],"ex":["12 miesięcy kontra całe życie",["Kredyt 3-letni, EAD = 100 (dla prostoty stałe), LGD = 40%, PD w kolejnych latach: 2%, 3%, 3%, stopa 5%.","Koszyk 1: ECL = 0,02 × 0,4 × 100 / 1,05 ≈ 0,76.","Koszyk 2: ECL = 40 × (0,02/1,05 + 0,03/1,05² + 0,03/1,05³) ≈ 2,89.","Przejście do koszyka 2 prawie czterokrotnie zwiększa odpis."]]},"par":[["PDₜ, LGDₜ, EADₜ","parametry w kolejnych okresach","ECL jest agregatem – szacuje się parametry składowe (krzywe lifetime)."],["wₛ","wagi scenariuszy","Prawdopodobieństwa scenariuszy makro – ocena ekspercka wsparta rozkładem prognoz."]]},{"id":"pdlt","d":"K1","g":"ECL · MSSF 9","n":"PD lifetime","o":"krzywe terminowe PD","k":"EL","s":"Struktura terminowa PD w całym życiu ekspozycji: z migracji, modeli przeżycia albo dopasowanych rozkładów (np. Weibull).","idea":"PD_cum(t) = 1 − S(t)","use":"ECL w koszykach 2 i 3.","u":5,"reg":"MSSF 9, par. 5.5.3 i 5.5.17 (oczekiwane straty w całym okresie życia); Rekomendacja R","old":"","ot":"Krzywa lifetime","otc":"#b5679a","det":{"p":["PD lifetime to krzywa: jakie jest prawdopodobieństwo defaultu w każdym kolejnym roku (PD krańcowe) i łącznie do danego momentu (PD skumulowane). Jest potrzebna do ECL w koszykach 2 i 3 oraz do wyceny i cen kredytów długoterminowych.","Buduje się ją kilkoma sposobami. Z macierzy migracji – mnożąc roczne macierze. Z modeli przeżycia – estymując funkcję hazardu w czasie. Z dopasowanych rozkładów (np. Weibulla), które dobrze oddają kształt ryzyka: rosnące w pierwszych latach kredytu, potem malejące. Albo z krzywych vintage (kohort udzieleń), obserwując, jak defaultowały wcześniejsze roczniki.","Krzywą trzeba połączyć z prognozami makro (PD punktowe w pierwszych latach, powrót do średniej w dalszych) i z warunkiem przeżycia – default w roku 5 możliwy jest tylko u klientów, którzy przetrwali 4 lata."],"ex":["Stały hazard, rosnące PD skumulowane",["Hazard roczny 2%, stały w czasie.","PD skumulowane po roku: 2%; po 5 latach: 1 − 0,98⁵ ≈ 9,6%; po 10 latach ≈ 18,3%.","PD krańcowe w roku 5: 0,98⁴ × 2% ≈ 1,84%.","Krańcowe maleje, bo w puli zostaje coraz mniej klientów."]]},"par":[["PD(t)","krzywa PD w horyzoncie","Z migracji, modelu hazardu albo dopasowanego rozkładu (np. Weibull: parametry kształtu i skali)."]]},{"id":"lgdlt","d":"K1","g":"ECL · MSSF 9","n":"LGD lifetime","o":"MSSF 9, LGD w czasie","k":"EL","s":"LGD dla każdego przyszłego okresu życia kredytu – zmienia się ze spłatą salda, wartością zabezpieczenia i scenariuszem makro.","idea":"LGD_t = f(LTV_t, ceny zabezpieczeń_t, cure rate)","use":"ECL lifetime w koszykach 2 i 3.","u":4,"reg":"MSSF 9, par. 5.5.17, B5.5.55 (zabezpieczenia); Rekomendacja R","old":"","ot":"Krzywa lifetime","otc":"#b5679a","det":{"p":["W MSSF 9 odpis w koszykach 2 i 3 liczy się na całe życie kredytu, więc potrzebne jest LGD nie jedno, ale dla każdego przyszłego okresu: jaka będzie strata, jeśli klient zbankrutuje w roku 1, 5 czy 10. Strata zmienia się w czasie, bo zmienia się relacja salda do zabezpieczenia.","W kredytach hipotecznych saldo spada z harmonogramem, a wartość nieruchomości zmienia się z rynkiem – wskaźnik LTV, a z nim LGD, zwykle maleje z wiekiem kredytu. Model LGD lifetime łączy więc prognozę salda (harmonogram, przedpłaty), prognozę wartości zabezpieczenia (indeksy cen w scenariuszach makro) i zależność LGD od LTV, często w podziale na prawdopodobieństwo wyzdrowienia i stratę dla niewyzdrowionych. Dla kredytów niezabezpieczonych krzywa zależy od wieku kredytu i skuteczności windykacji.","Ważna jest spójność z PD i EAD lifetime: wszystkie trzy krzywe muszą wynikać z tych samych scenariuszy makro i założeń o spłatach."],"ex":["Hipoteka w czasie",["Kredyt na 25 lat: w roku 1 LTV = 90% → LGD = 25%.","W roku 5 saldo spadło, LTV = 70% → LGD = 15%; w roku 10 LTV = 50% → LGD = 8%.","Stałe LGD 25% w całym życiu zawyżyłoby ECL lifetime.","W scenariuszu spadku cen mieszkań o 15% cała krzywa LGD przesuwa się w górę."]]},"par":[["LGD(t)","krzywa LGD w czasie","Zależność LGD od LTV i czasu oraz prognoza wartości zabezpieczeń w scenariuszach."]]},{"id":"eadlt","d":"K1","g":"ECL · MSSF 9","n":"EAD lifetime","o":"harmonogram, przedpłaty","k":"EL","s":"Ekspozycja w kolejnych okresach życia kredytu: harmonogram spłat, przedpłaty i wykorzystanie limitów odnawialnych.","idea":"EAD_t = saldo_t (harmonogram, CPR, CCF)","use":"ECL lifetime.","u":4,"reg":"MSSF 9, par. 5.5.19–5.5.20 (okres ekspozycji, limity odnawialne); Rekomendacja R","old":"","ot":"Krzywa lifetime","otc":"#b5679a","det":{"p":["W MSSF 9 odpis dla koszyków 2 i 3 liczy się na cały okres życia ekspozycji, a więc potrzebna jest EAD nie na jeden moment, ale na każdy przyszły okres. Dla kredytu ratalnego punktem wyjścia jest harmonogram spłat, ale realne saldo spada szybciej, bo część klientów spłaca wcześniej.","EAD lifetime łączy więc trzy elementy: harmonogram (kontraktowy spadek salda), przedpłaty (częściowe i całkowite, modelowane współczynnikiem CPR) oraz – dla produktów odnawialnych – wykorzystanie limitów w czasie (CCF i oczekiwany okres życia karty, który nie jest równy terminowi umowy).","Każdy z tych elementów zmienia ECL: wyższe przedpłaty skracają okres narażenia i obniżają odpis, a dłuższy behawioralny okres życia kart go zwiększa."],"ex":["Przedpłaty skracają ekspozycję",["Kredyt 120 tys. zł na 10 lat; według harmonogramu po 3 latach saldo wynosi 90 tys. zł.","Przedpłaty CPR = 8% rocznie: oczekiwane saldo ≈ 90 × 0,92³ ≈ 70 tys. zł.","EAD w roku 4 jest niższe o ok. 22%.","O tyle samo spada część ECL przypisana do tego roku."]]},"par":[["CPR","stopa przedpłat","Z modelu przedpłat na danych miesięcznych."],["CCF(t)","wykorzystanie limitów w czasie","Krzywe wykorzystania i behawioralny okres życia produktów odnawialnych."]]},{"id":"sicr","d":"K1","g":"ECL · MSSF 9","n":"SICR i koszyki","o":"istotny wzrost ryzyka","k":"EL","s":"Kryteria przeniesienia do koszyka 2: względny wzrost PD, przesłanki jakościowe, 30 dni opóźnienia jako granica bezpieczeństwa.","idea":"PD_dziś / PD_początkowe > próg","use":"Podział portfela na koszyki 1–2–3.","u":5,"reg":"MSSF 9, par. 5.5.3–5.5.11; Rekomendacja R KNF","old":"","ot":"Klasyfikacja","otc":"#b08a1e","det":{"p":["SICR (Significant Increase in Credit Risk) to próg, który decyduje o przejściu kredytu z koszyka 1 do 2, czyli z odpisu 12-miesięcznego na odpis lifetime. Ponieważ ta zmiana potrafi kilkukrotnie zwiększyć odpis, definicja SICR ma ogromny wpływ na wynik banku.","Kryteria są trzy. Ilościowe: porównanie obecnego PD lifetime z PD oczekiwanym w momencie udzielenia kredytu – zwykle względny wzrost (np. ponad 2,5 raza) połączony z minimalnym wzrostem bezwzględnym. Jakościowe: lista obserwacyjna, restrukturyzacja (forbearance), sygnały ostrzegawcze. I granica bezpieczeństwa: 30 dni przeterminowania oznacza SICR niezależnie od modelu.","Dobra definicja reaguje wcześnie, ale nie powoduje ciągłego przeskakiwania kredytów między koszykami. Walidacja sprawdza m.in., ile kredytów trafia do koszyka 2 przed defaultem i jak długo w nim przebywa."],"ex":["Kiedy kredyt zmienia koszyk",["PD w dniu udzielenia: 1%, dziś: 3,5% → wzrost 3,5 raza (próg: 2,5 raza).","Kredyt przechodzi do koszyka 2.","Odpis rośnie z 12-miesięcznego (0,5 tys. zł) do lifetime (2,2 tys. zł).","Gdyby klient spóźnił się 31 dni, przeszedłby niezależnie od PD."]]},"par":[["c","próg względnego wzrostu PD","Kalibrowany tak, by koszyk 2 wychwytywał pogorszenie z wyprzedzeniem przy rozsądnej stabilności."]]},{"id":"fli","d":"K1","g":"ECL · MSSF 9","n":"Scenariusze makro (FLI)","o":"modele satelitarne","k":"EL","s":"PD i LGD warunkowe od prognoz makroekonomicznych; kilka scenariuszy ważonych prawdopodobieństwem.","idea":"PD_s = f(PKB_s, stopy_s, bezrobocie_s)","use":"ECL forward-looking, stres testy.","u":5,"reg":"MSSF 9, par. 5.5.17 lit. a i c (scenariusze ważone, informacje o przyszłości); Rekomendacja R","old":"","ot":"Prognoza","otc":"#3f8a77","det":{"p":["MSSF 9 wymaga, żeby odpis uwzględniał rozsądne prognozy przyszłości (forward-looking information). Dlatego parametry PD i LGD nie mogą bazować wyłącznie na historii – trzeba je powiązać z prognozami gospodarki.","Robi się to modelami satelitarnymi: na danych historycznych szacuje się zależność wskaźnika defaultów (albo indeksu jakości portfela) od zmiennych makro – PKB, bezrobocia, stóp procentowych, cen nieruchomości. Następnie podstawia się prognozy z kilku scenariuszy: bazowego, pesymistycznego i optymistycznego, każdy z wagą prawdopodobieństwa.","Ważne jest, że ECL liczy się dla każdego scenariusza osobno, a dopiero potem waży. Ponieważ straty rosną nieliniowo w złych scenariuszach, wynik ważony jest wyższy niż ECL ze scenariusza bazowego – to tzw. efekt nieliniowości."],"ex":["Trzy scenariusze, jeden odpis",["Bazowy (waga 60%): ECL = 10 mln zł. Pesymistyczny (25%): 16 mln zł. Optymistyczny (15%): 7 mln zł.","ECL ważony = 0,6 × 10 + 0,25 × 16 + 0,15 × 7 = 11,05 mln zł.","To o 10,5% więcej niż w scenariuszu bazowym.","Różnica to koszt asymetrii: zły scenariusz boli bardziej, niż cieszy dobry."]]},"par":[["βᴹ","wrażliwość PD i LGD na makro","Regresja wskaźnika defaultów na zmiennych makro (szeregi czasowe, kointegracja)."],["wₛ","wagi scenariuszy","Ekspercko, często z rozkładu prognoz."]]},{"id":"vasicek","d":"K2","g":"","n":"ASRF / model Vasicka","o":"Vasicek 1987, Gordy 2003","k":"UL","s":"Jednoczynnikowy model portfela nieskończenie ziarnistego. Default dłużnika zależy od wspólnego czynnika gospodarki i czynnika własnego.","idea":"PD(z) = N[(N⁻¹(PD) + √ρ · N⁻¹(0,999)) / √(1 − ρ)]","use":"Podstawa wzoru IRB.","u":3,"reg":"","old":"","ot":"Kwantyl / rozkład","otc":"#8a4f8f","det":{"p":["Model Vasicka odpowiada na pytanie: jak duża może być strata całego portfela kredytów w bardzo złym roku. Zakłada, że sytuacja każdego dłużnika zależy od dwóch rzeczy: wspólnego czynnika – kondycji gospodarki – i czynnika indywidualnego. Korelacja ρ mówi, jak silnie dłużnicy reagują na wspólny czynnik.","Jeśli portfel jest bardzo ziarnisty (wiele małych ekspozycji), ryzyko indywidualne się dywersyfikuje i zostaje tylko wspólne. Wtedy odsetek defaultów w portfelu zależy wyłącznie od stanu gospodarki. Ustalając bardzo zły stan gospodarki – np. taki, który zdarza się raz na tysiąc lat (kwantyl 99,9%) – dostajemy „warunkowe PD”: odsetek defaultów w kryzysie.","To dokładnie konstrukcja wzoru IRB (Gordy pokazał w 2003 roku, kiedy taki podział kapitału na ekspozycje jest poprawny – model ASRF). Strata nieoczekiwana to różnica między stratą w kryzysie a stratą oczekiwaną."],"ex":["Odsetek defaultów w kryzysie",["PD = 1%, korelacja ρ = 15%, kwantyl 99,9%.","Warunkowe PD = N[(−2,326 + √0,15 × 3,090) / √0,85] = N(−1,22) ≈ 11%.","W „roku raz na tysiąc lat” zdefaultuje ok. 11% portfela zamiast 1%.","Przy LGD 45%: strata nieoczekiwana ≈ 0,45 × (11% − 1%) = 4,5% ekspozycji."]]},"par":[["ρ","korelacja aktywów (czynnik wspólny)","Z wahań odsetka defaultów w czasie – metoda momentów albo MLE."]]},{"id":"irb","d":"K2","g":"","n":"Wzór IRB","o":"Bazylea II / III, CRR","k":"UL","s":"Wymóg kapitałowy na stratę nieoczekiwaną z PD, LGD, EAD i zapadalności; korelacja zależy od klasy ekspozycji.","idea":"K = LGD · [PD(z) − PD] · MA,  RWA = 12,5 · K · EAD","use":"RWA kredytowe, CET1.","u":3,"reg":"CRR art. 142–191 (metoda IRB), art. 153–154 (wzory na RWA)","old":"","ot":"Wzór / agregacja","otc":"#4b4740","det":{"p":["Wzór IRB to regulacyjna wersja modelu Vasicka. Bank sam szacuje PD (a w metodzie zaawansowanej także LGD i EAD), a wzór zamienia te parametry na wymóg kapitałowy. Korelacje nie są szacowane przez bank – ustala je regulator w zależności od klasy ekspozycji (dla przedsiębiorstw maleją wraz z PD, dla hipotek wynoszą 15%, dla detalu odnawialnego 4%).","Wymóg K pokrywa tylko stratę nieoczekiwaną: LGD × (warunkowe PD − PD), skorygowane o efektywny termin zapadalności (dłuższe kredyty mogą się pogorszyć, zanim zostaną spłacone). Stratę oczekiwaną bank pokrywa odpisami; jeśli odpisy są niższe od EL regulacyjnej, różnica obniża CET1.","Na koniec RWA = 12,5 × K × EAD, a minimalny kapitał to 8% RWA. Waga ryzyka (RWA / EAD) mocno reaguje na PD i LGD – dlatego jakość modeli parametrów przekłada się bezpośrednio na kapitał banku."],"ex":["Waga ryzyka kredytu dla firmy",["PD = 1%, LGD = 45%, termin 2,5 roku → korelacja ρ ≈ 19,3%, korekta terminu ≈ 1,26.","Warunkowe PD ≈ 14,0% → K = 0,45 × (14,0% − 1%) × 1,26 ≈ 7,4%.","RWA = 12,5 × 7,4% ≈ 92% ekspozycji.","Na 100 mln zł kredytu bank potrzebuje 92 mln RWA, czyli ok. 7,4 mln zł kapitału (8%)."]]},"par":[["PD","prawdopodobieństwo defaultu","Szacuje bank – długookresowa średnia z marżą ostrożności."],["LGD","strata w razie defaultu","Szacuje bank w metodzie zaawansowanej (downturn)."],["EAD/CCF","ekspozycja","Szacuje bank w metodzie zaawansowanej."],["M","efektywny termin","Wyliczany z przepływów; korelacja i kwantyl są regulacyjne."]]},{"id":"sa","d":"K2","g":"","n":"Metoda standardowa","o":"CRR3, output floor","k":"UL","s":"Wagi ryzyka według klasy ekspozycji i ratingu zewnętrznego; od CRR3 także dolny próg dla modeli wewnętrznych (72,5%).","idea":"RWA = Σ waga · ekspozycja","use":"Banki bez IRB, porównanie z IRB.","u":5,"reg":"CRR art. 111–141 (metoda standardowa); CRR3 – output floor, art. 92","old":"","ot":"Wzór / agregacja","otc":"#4b4740","det":{"p":["Metoda standardowa to podejście „z tabeli”: ekspozycje dzieli się na klasy (rządy, banki, przedsiębiorstwa, detal, hipoteki, ekspozycje przeterminowane…), a każda klasa ma wagę ryzyka zależną od ratingu zewnętrznego lub od cech ekspozycji, np. wskaźnika LTV kredytu hipotecznego.","Jest prosta i porównywalna między bankami, ale mało czuła na rzeczywiste ryzyko: dwie firmy bez ratingu dostają tę samą wagę 100%, niezależnie od kondycji. CRR3 (Bazylea III w ostatecznej wersji) uczyniła ją bardziej wrażliwą – np. wagi hipotek zależą od LTV, a dla nieocenianych przedsiębiorstw inwestycyjnej jakości przewidziano niższą wagę.","Metoda standardowa zyskała nową rolę jako dolny próg (output floor): RWA z modeli wewnętrznych nie mogą spaść poniżej 72,5% RWA wyliczonych metodą standardową. Dlatego banki IRB i tak muszą ją liczyć."],"ex":["Ta sama kwota, różne wagi",["Kredyt dla firmy bez ratingu: 100 mln × 100% = 100 mln RWA → kapitał 8 mln zł.","Kredyt hipoteczny z LTV 50%: 100 mln × 20% = 20 mln RWA → kapitał 1,6 mln zł.","Bank IRB ma RWA 50 mln przy RWA standardowych 100 mln → próg 72,5 mln.","Bank musi przyjąć 72,5 mln RWA zamiast 50 mln."]]},"par":[["—","brak parametrów szacowanych","Wagi ryzyka są nadzorcze; bank klasyfikuje ekspozycje i stosuje ratingi zewnętrzne."]]},{"id":"cmetrics","d":"K2","g":"","n":"CreditMetrics","o":"J.P. Morgan, 1997","k":"UL","s":"Rozkład wartości portfela z migracji ratingów; zależność między dłużnikami przez skorelowane zwroty z aktywów.","idea":"wartość portfela w 1 roku z symulacji migracji","use":"Kapitał ekonomiczny, limity koncentracji.","u":2,"reg":"","old":"","ot":"Kwantyl / rozkład","otc":"#8a4f8f","det":{"p":["CreditMetrics (J.P. Morgan, 1997) liczy rozkład wartości portfela kredytowego za rok. Kluczowa obserwacja: wartość kredytu lub obligacji zmienia się nie tylko przy defaulcie, ale też przy zmianie ratingu – obniżka ratingu podnosi wymagany spread i obniża wartość.","Dla każdego dłużnika model losuje zwrot z jego aktywów; progi wyznaczone z macierzy migracji decydują, w którą klasę ratingową trafi (albo w default). Zwroty dłużników są skorelowane – zależą od wspólnych czynników branżowych i krajowych – więc w złych scenariuszach wielu dłużników pogarsza się jednocześnie. Po symulacji wycenia się każdą pozycję według nowego ratingu.","Wynik to pełny rozkład wartości portfela: wartość oczekiwana, odchylenie i kwantyle, z których liczy się kapitał ekonomiczny. Podejście łączy więc migracje, model Mertona i korelacje – i daje miarę ryzyka spójną z wyceną."],"ex":["Jedna obligacja BBB",["Za rok: awans (5%) → 101; bez zmian (88%) → 100; spadek do BB (5%) → 96; do B (1,8%) → 90; default (0,2%) → 55.","Wartość oczekiwana ≈ 99,6.","Kwantyl 1% = 90 (z prawdopodobieństwem ok. 2% wartość spada do 90 lub niżej).","Kapitał na 99% ≈ 99,6 − 90 = 9,6 – głównie z migracji, nie z defaultu."]]},"par":[["ρ","korelacje zwrotów aktywów","Model czynnikowy na danych akcyjnych i branżowych."],["P","macierz migracji","Z danych ratingowych."],["sₖ","spready w klasach","Z rynku – do wyceny pozycji po migracji."]]},{"id":"crplus","d":"K2","g":"","n":"CreditRisk+","o":"Credit Suisse FP, 1997","k":"UL","s":"Podejście aktuarialne: liczba defaultów z rozkładu Poissona, zmienność przez czynniki sektorowe o rozkładzie gamma; rozkład strat liczony analitycznie.","idea":"N ~ Poisson(λ), λ = PD · Σ wₖ · Sₖ,  rekurencja Panjera","use":"Kapitał ekonomiczny portfela detalicznego i MŚP.","u":2,"reg":"","old":"","ot":"Kwantyl / rozkład","otc":"#8a4f8f","det":{"p":["CreditRisk+ (Credit Suisse Financial Products, 1997) przeniósł do ryzyka kredytowego metody ubezpieczeniowe. Nie modeluje wartości firm ani migracji – interesuje go tylko liczba defaultów i strata. Liczba defaultów w grupie podobnych kredytów ma rozkład Poissona z parametrem równym sumie PD.","Sam Poisson dałby zbyt cienki ogon, bo zakłada niezależność defaultów. Dlatego model wprowadza czynniki sektorowe o rozkładzie gamma: w złym roku intensywność defaultów w całym sektorze rośnie jednocześnie. Mieszanka Poissona i gammy daje rozkład z grubszym ogonem, a strukturę strat liczy się analitycznie (rekurencją Panjera), bez symulacji.","Model jest szybki, potrzebuje niewielu danych (PD, ekspozycja netto, przypisanie do sektorów) i dobrze nadaje się do portfeli detalicznych i MŚP. Ta sama matematyka – częstość × dotkliwość – stoi za LDA w ryzyku operacyjnym i za modelami ubezpieczeniowymi."],"ex":["Sto kredytów",["100 kredytów, PD = 2% każdy, strata na kredycie = 1 → średnio 2 defaulty (EL = 2).","Poisson(2): P(co najwyżej 5 defaultów) = 98,3%, P(co najwyżej 6) = 99,5% → kwantyl 99% = 6.","Kapitał (UL) = 6 − 2 = 4.","Z czynnikiem sektorowym (zmienność PD) ogon grubieje – kwantyl 99% rośnie np. do 8–9."]]},"par":[["σₖ","zmienność czynników sektorowych","Zmienność PD w sektorze – z historii odsetka defaultów."],["PD","PD dłużników","Z modeli PD banku."]]},{"id":"copula","d":"K2","g":"","n":"Kopuły","o":"Li 2000; Gauss, t, Archimedesa","k":"UL","s":"Oddzielają rozkłady brzegowe od struktury zależności; kopuła t lepiej oddaje wspólne defaulty w ogonie.","idea":"F(x₁,…,xₙ) = C(F₁(x₁),…,Fₙ(xₙ))","use":"Portfele kredytowe, CDO, agregacja ryzyk.","u":2,"reg":"","old":"","ot":"Kwantyl / rozkład","otc":"#8a4f8f","det":{"p":["Kopuła to narzędzie do opisywania zależności między zmiennymi niezależnie od ich rozkładów brzegowych. Twierdzenie Sklara mówi, że każdy rozkład wielowymiarowy można rozłożyć na rozkłady pojedynczych zmiennych i kopułę, która je wiąże.","W ryzyku kredytowym kopuła Gaussa (David Li, 2000) stała się standardem w wycenie portfelowych instrumentów, takich jak CDO. Jej słabość: przy tej samej korelacji słabo odwzorowuje wspólne zdarzenia skrajne – w kryzysie defaulty pojawiają się razem częściej, niż przewiduje. Kopuła t-Studenta ma zależność w ogonach i lepiej oddaje kryzysy; kopuły Archimedesa (Claytona, Gumbela) pozwalają na asymetrię.","Kopuły stosuje się też do agregacji ryzyk w ICAAP: łączą rozkłady strat kredytowych, rynkowych i operacyjnych w jeden rozkład całkowitej straty."],"ex":["Ta sama korelacja, inny ogon",["Dwa kredyty, PD = 5% każdy, korelacja 30%.","Niezależność: oba defaulty jednocześnie z prawdopodobieństwem 0,25%.","Kopuła Gaussa: kilkukrotnie więcej; kopuła t (mało stopni swobody): jeszcze więcej.","W portfelu tysięcy kredytów ta różnica decyduje o kwantylu 99,9%."]]},"par":[["ρ","korelacja w kopule","MLE albo z tau Kendalla."],["ν","stopnie swobody (kopuła t)","MLE – decyduje o zależności w ogonach."]]},{"id":"varp","d":"R","g":"VaR","n":"VaR wariancji–kowariancji","o":"parametryczny, delta-normalny","k":"UL","s":"Zakłada normalne zwroty i liniowy portfel; VaR wynika z odchylenia standardowego portfela.","idea":"VaR = z_α · √(w′Σw) · √h","use":"Szybkie limity, agregacja.","u":3,"reg":"","old":"","ot":"Kwantyl / rozkład","otc":"#8a4f8f","det":{"p":["VaR (Value at Risk) odpowiada na pytanie: jakiej straty nie przekroczymy z prawdopodobieństwem np. 99% w zadanym horyzoncie. Metoda wariancji–kowariancji liczy go analitycznie, zakładając, że zwroty czynników ryzyka mają rozkład normalny, a wartość portfela zależy od nich liniowo.","Potrzebne są dwie rzeczy: wrażliwości portfela na czynniki ryzyka (delty, PV01) i macierz kowariancji zwrotów tych czynników. Odchylenie standardowe portfela wynika z ich iloczynu, a VaR to odchylenie razy kwantyl rozkładu normalnego (2,33 dla 99%). Horyzont wydłuża się regułą pierwiastka z czasu.","Zalety: szybkość, łatwa agregacja i podział ryzyka na pozycje. Wady: rozkład normalny ma za cienkie ogony, a dla opcji zależność nie jest liniowa – metoda wtedy zaniża ryzyko."],"ex":["VaR portfela akcji",["Wartość portfela: 10 mln zł, dzienne odchylenie stopy zwrotu: 1,2%.","VaR 1-dniowy 99% = 10 mln × 1,2% × 2,326 ≈ 279 tys. zł.","VaR 10-dniowy = 279 tys. × √10 ≈ 883 tys. zł.","Średnio raz na 100 dni strata przekroczy 279 tys. zł."]]},"par":[["Σ","macierz kowariancji czynników","Z historii zwrotów, często ważonej wykładniczo (EWMA)."]]},{"id":"varh","d":"R","g":"VaR","n":"VaR symulacji historycznej","o":"historyczny, BRW, FHS","k":"UL","s":"Kwantyl empiryczny z historycznych zmian czynników; wersje ważone wiekiem (BRW) i filtrowane zmiennością (FHS).","idea":"VaR = −kwantyl_α {ΔV(scenariusz historyczny)}","use":"Najczęstsza metoda w bankach.","u":5,"reg":"","old":"","ot":"Kwantyl / rozkład","otc":"#8a4f8f","det":{"p":["Symulacja historyczna nie zakłada żadnego rozkładu. Bierze rzeczywiste zmiany czynników ryzyka z ostatnich np. 500 dni i pyta: co stałoby się z dzisiejszym portfelem, gdyby jutro powtórzył się każdy z tych dni. Daje to 500 scenariuszy wyniku; VaR to odpowiedni kwantyl – dla 99% piąta najgorsza strata.","Metoda naturalnie uwzględnia grube ogony, asymetrię i korelacje z danych, a przy pełnej wycenie także nieliniowość opcji. Słabością jest całkowita zależność od okna historycznego: jeśli w ostatnich dwóch latach nie było kryzysu, VaR go nie zobaczy, a gdy dzień kryzysowy wypadnie z okna, VaR nagle spada.","Ulepszenia: ważenie scenariuszy wiekiem (BRW – nowsze dni ważą więcej) i filtrowana symulacja historyczna (FHS), która przeskalowuje historyczne zwroty do bieżącej zmienności z modelu GARCH."],"ex":["Piąta najgorsza strata",["500 scenariuszy dziennych wyników portfela.","Pięć najgorszych: −410, −380, −350, −330, −300 tys. zł.","VaR 99% = 300 tys. zł (1% z 500 scenariuszy to 5).","Gdyby w oknie nie było dnia −410, VaR by się nie zmienił – ale ES tak."]]},"par":[["T","okno historyczne i wagi","Długość okna i ważenie (BRW, FHS) – wybór modelowy, a nie estymacja."]]},{"id":"varmc","d":"R","g":"VaR","n":"VaR Monte Carlo","o":"symulacja z pełną wyceną","k":"UL","s":"Losowanie czynników ryzyka z założonego rozkładu i pełna wycena portfela; obsługuje opcje i nieliniowość.","idea":"VaR = −kwantyl_α {ΔV(scenariusz losowy)}","use":"Portfele opcyjne, CVA, IMM.","u":3,"reg":"","old":"","ot":"Kwantyl / rozkład","otc":"#8a4f8f","det":{"p":["Symulacja Monte Carlo losuje tysiące scenariuszy czynników ryzyka z założonego modelu – np. wielowymiarowego rozkładu t ze zmiennością z GARCH, procesów stóp procentowych, skoków cen – i dla każdego scenariusza wycenia cały portfel od nowa. VaR to kwantyl rozkładu tak uzyskanych wyników.","To najbardziej elastyczna metoda: obsługuje opcje i inne instrumenty nieliniowe, zależność ścieżkową, dłuższe horyzonty i dowolne rozkłady. Jest też podstawą modeli ekspozycji kontrahenta (EE, PFE) i CVA.","Koszty to czas obliczeń (pełna wycena tysięcy scenariuszy) i ryzyko modelu: wynik jest tak dobry, jak założenia o rozkładach i korelacjach. Dlatego wyniki Monte Carlo porównuje się z symulacją historyczną i poddaje backtestingowi."],"ex":["Portfel opcji",["Portfel sprzedanych opcji kupna na indeks: delta 0, ale gamma ujemna.","VaR wariancji–kowariancji (liniowy) ≈ 0 – wygląda na bezpieczny.","Monte Carlo: 10 000 scenariuszy z pełną wyceną; setna najgorsza strata = 1,8 mln zł.","VaR 99% = 1,8 mln zł – ryzyko widać dopiero przy nieliniowej wycenie."]]},"par":[["θ","parametry procesów czynników","Zmienności, korelacje i ogony (np. rozkład t) – estymowane z danych."]]},{"id":"garch","d":"R","g":"Zmienność","n":"GARCH i rodzina","o":"Engle 1982, Bollerslev 1986","k":"UL","s":"Zmienność warunkowa reagująca na szoki; EGARCH i GJR-GARCH oddają asymetrię (złe wiadomości mocniej).","idea":"σ²ₜ = ω + α · r²ₜ₋₁ + β · σ²ₜ₋₁","use":"VaR, FHS, wycena opcji.","u":2,"reg":"","old":"","ot":"Prognoza","otc":"#3f8a77","det":{"p":["Zmienność na rynkach finansowych nie jest stała – zbija się w skupiska: po dużych ruchach przychodzą kolejne duże ruchy, a spokojne okresy trwają długo. Robert Engle (ARCH, 1982, Nobel 2003) i Tim Bollerslev (GARCH, 1986) zaproponowali modele, w których dzisiejsza wariancja zależy od wczorajszych szoków i wczorajszej wariancji.","W GARCH(1,1) wariancja ma trzy składniki: stałą ω, reakcję na ostatni szok (α) i pamięć poprzedniej zmienności (β). Gdy α + β < 1, zmienność wraca do poziomu długookresowego ω / (1 − α − β) – w przeciwieństwie do EWMA. Rozszerzenia oddają asymetrię: EGARCH (Nelson) i GJR-GARCH sprawiają, że spadki podnoszą zmienność mocniej niż wzrosty.","GARCH służy do prognoz zmienności w VaR, do filtrowanej symulacji historycznej, wyceny opcji i stres testów zmienności."],"ex":["Szok i powrót do normy",["ω = 0,000002, α = 0,08, β = 0,90 → zmienność długookresowa √(0,000002 / 0,02) = 1%.","Po spadku o 3%: σ² = 0,000002 + 0,08 × 0,0009 + 0,9 × 0,0001 = 0,000164 → 1,28%.","Trwałość α + β = 0,98: nadwyżka zmienności maleje o 2% dziennie.","Połowa szoku wygasa po ok. 35 dniach."]]},"par":[["ω","stała","MLE na szeregu zwrotów."],["α","reakcja na ostatni szok","MLE."],["β","trwałość zmienności","MLE; α + β < 1 zapewnia powrót do średniej."]]},{"id":"rm","d":"R","g":"Zmienność","n":"RiskMetrics (EWMA)","o":"J.P. Morgan, 1994; RM2006","k":"UL","s":"Standard szacowania zmienności i korelacji (EWMA, λ = 0,94) wraz z danymi, który upowszechnił VaR parametryczny. Nie czwarta metoda VaR – dostarcza jej wejście (σ i korelacje).","idea":"σ²ₜ = λ · σ²ₜ₋₁ + (1 − λ) · r²ₜ₋₁","use":"VaR parametryczny, zmienność do FHS.","u":3,"reg":"","old":"","ot":"Prognoza","otc":"#3f8a77","det":{"p":["RiskMetrics to nie osobna metoda liczenia ryzyka, lecz metodyka i zbiór danych, które J.P. Morgan opublikował w 1994 roku – i które spopularyzowały VaR w całej branży. Firma udostępniła za darmo dokument techniczny i codzienne dane o zmiennościach i korelacjach setek instrumentów. W pierwszej wersji był to po prostu VaR wariancji–kowariancji (parametryczny) z określonym sposobem szacowania zmienności; późniejsze wersje i spółka RiskMetrics Group objęły także symulację historyczną i Monte Carlo.","Dlatego na mapie RiskMetrics stoi obok GARCH, a nie obok trzech metod VaR: jego wkładem jest sposób szacowania zmienności i korelacji, który zasila VaR parametryczny (a dziś także filtrowaną symulację historyczną). Sercem jest prosty model zmienności: wykładniczo ważona średnia ruchoma (EWMA). Dzisiejsza wariancja to 94% wczorajszej wariancji plus 6% wczorajszego kwadratu stopy zwrotu. Nowe informacje szybko podnoszą zmienność, a stare stopniowo tracą znaczenie. Parametr λ = 0,94 dobrano empirycznie dla danych dziennych. Wersja RiskMetrics 2006 zastąpiła jeden parametr kombinacją kilku skal czasowych (długa pamięć).","EWMA to szczególny przypadek modelu GARCH bez powrotu do średniej długookresowej – dlatego dobrze śledzi bieżące ryzyko, ale nie nadaje się do długoterminowych prognoz zmienności."],"ex":["Zmienność po złym dniu",["Wczorajsza zmienność dzienna: 1%, wczorajsza stopa zwrotu: −3%.","σ² = 0,94 × 0,01² + 0,06 × 0,03² = 0,000094 + 0,000054 = 0,000148.","Dzisiejsza zmienność: √0,000148 ≈ 1,22%.","Jeden zły dzień podnosi VaR parametryczny o 22%."]]},"par":[["λ","współczynnik wygaszania","0,94 dla danych dziennych – dobrany empirycznie."]]},{"id":"es","d":"R","g":"Ogon","n":"Expected Shortfall / FRTB","o":"Bazylea, FRTB","k":"UL","s":"Średnia strata poza kwantylem; miara spójna. W FRTB ES 97,5% z horyzontami płynności, NMRF i DRC.","idea":"ES_α = E[L | L ≥ VaR_α]","use":"Kapitał na ryzyko rynkowe (FRTB).","u":3,"reg":"FRTB (Bazylea, MAR33); CRR art. 325ba–325bp (alternatywna metoda modeli wewnętrznych)","old":"","ot":"Kwantyl / rozkład","otc":"#8a4f8f","det":{"p":["Expected Shortfall (ES, warunkowy VaR) odpowiada na pytanie, którego VaR nie zadaje: jeśli już zdarzy się zły dzień poza kwantylem, to ile średnio stracimy. ES to średnia strat większych od VaR.","ES ma ważne zalety. Jest miarą spójną (subaddytywną) – ryzyko połączonych portfeli nie przekracza sumy ryzyk, więc dywersyfikacja zawsze pomaga, czego VaR nie gwarantuje. I widzi kształt ogona: dwa portfele z tym samym VaR mogą mieć zupełnie inne ES, jeśli jeden z nich może przynieść katastrofalną stratę.","W FRTB (nowym reżimie ryzyka rynkowego Bazylei) ES 97,5% zastąpił VaR 99% w modelach wewnętrznych. Liczony jest z okresu skrajnego stresu, z różnymi horyzontami płynności dla czynników ryzyka (10–120 dni), a czynniki bez wiarygodnych danych (NMRF) i ryzyko defaultu (DRC) mają osobne narzuty."],"ex":["Średnia z ogona",["200 scenariuszy; 97,5% → ogon to 5 najgorszych.","Straty w ogonie: 500, 420, 380, 350, 300 tys. zł.","VaR 97,5% ≈ 300 tys. zł; ES = (500 + 420 + 380 + 350 + 300) / 5 = 390 tys. zł.","Gdyby najgorsza strata wynosiła 2 mln, VaR stałby w miejscu, a ES wzrósłby do 690 tys."]]},"par":[["q","rozkład strat w ogonie","Z symulacji okresu stresu; horyzonty płynności są nadzorcze."]]},{"id":"evt","d":"R","g":"Ogon","n":"Teoria wartości ekstremalnych","o":"Pickands, Balkema–de Haan","k":"UL","s":"Modeluje sam ogon rozkładu: nadwyżki ponad próg (POT) z rozkładem GPD albo maksima blokowe (GEV).","idea":"P(X − u > y | X > u) ≈ GPD(ξ, β)","use":"VaR i ES w ogonie, dotkliwość w LDA.","u":1,"reg":"","old":"","ot":"Kwantyl / rozkład","otc":"#8a4f8f","det":{"p":["Teoria wartości ekstremalnych zajmuje się tylko ogonem rozkładu – rzadkimi, dużymi stratami, których w danych jest mało, a które decydują o kapitale. Zamiast dopasowywać rozkład do wszystkich obserwacji, dopasowuje go tylko do tych skrajnych.","Najczęstsza metoda to POT (Peaks over Threshold): wybiera się wysoki próg i modeluje nadwyżki ponad próg. Twierdzenie Pickandsa–Balkemy–de Haana mówi, że dla wysokich progów nadwyżki mają w przybliżeniu uogólniony rozkład Pareto (GPD). Jego parametr kształtu ξ mówi, jak gruby jest ogon: ξ > 0 oznacza ogon potęgowy, typowy dla rynków i strat operacyjnych. Alternatywa to metoda maksimów blokowych z rozkładem GEV.","EVT pozwala ekstrapolować poza dane – oszacować stratę raz na 1000 dni, mając 500 obserwacji – ale wymaga ostrożnego wyboru progu, bo wynik jest na niego wrażliwy."],"ex":["Ogon grubszy niż normalny",["Dzienne straty powyżej progu 2%: 50 przekroczeń w 10 latach.","Dopasowanie GPD daje ξ = 0,25 (ogon potęgowy).","Przykładowo: VaR 99,9% z EVT ≈ 7%, z rozkładu normalnego ≈ 3,8%.","Rozkład normalny zaniżyłby skrajne ryzyko prawie o połowę."]]},"par":[["ξ","parametr kształtu ogona","MLE na nadwyżkach ponad próg (GPD), razem z parametrem skali."],["u","próg","Wybór na wykresie średnich nadwyżek i stabilności ξ."]]},{"id":"stv","d":"R","g":"Ogon","n":"Stressed VaR","o":"Bazylea 2.5","k":"S","s":"VaR liczony na danych z 12-miesięcznego okresu skrajnego stresu dla portfela.","idea":"sVaR = VaR(okres stresu)","use":"Kapitał (przed FRTB), stres testy.","u":3,"reg":"CRR art. 365 (VaR i VaR w warunkach skrajnych)","old":"","ot":"Kwantyl / rozkład","otc":"#8a4f8f","det":{"p":["Kryzys 2008 roku pokazał, że VaR liczony na danych z ostatniego roku–dwóch jest najniższy tuż przed kryzysem – bo poprzedzający okres był spokojny. Reforma Bazylei 2.5 (2009) dodała więc Stressed VaR: ten sam model VaR, ale skalibrowany na danych z 12-miesięcznego okresu skrajnego stresu, istotnego dla portfela banku (np. 2008–2009).","Wymóg kapitałowy na ryzyko rynkowe w modelach wewnętrznych stał się sumą zwykłego VaR i sVaR (każdy z mnożnikiem), co mniej więcej podwoiło kapitał i ograniczyło jego procykliczność. W FRTB idea przetrwała: ES liczy się z danych okresu stresu.","Podobną logikę mają scenariusze historyczne w stres testach: co stałoby się z dzisiejszym portfelem, gdyby powtórzył się wrzesień 2008, marzec 2020 albo szok stóp z 2022 roku."],"ex":["Spokojne okno kontra kryzys",["VaR 10-dniowy 99% z danych z ostatnich 12 miesięcy: 2 mln zł.","Ten sam model na danych z lat 2008–2009: sVaR = 5,5 mln zł.","Wymóg ≈ 3 × 2 + 3 × 5,5 = 22,5 mln zł (przy minimalnych mnożnikach).","Sam VaR dałby 6 mln zł – prawie czterokrotnie mniej."]]},"par":[["T*","okres stresu","Wybór 12 miesięcy najgorszych dla portfela – kluczowa decyzja modelowa."]]},{"id":"mktsa","d":"R","g":"Metody standardowe","n":"Metoda standardowa (CRR)","o":"obecny wymóg w UE, „klocki”","k":"UL","s":"Wymóg z tabel nadzorczych osobno dla stóp, akcji, walut i towarów: ryzyko ogólne i szczególne pozycji netto.","idea":"K = Σ (pozycja × waga nadzorcza) w blokach ryzyka","use":"Wymóg na ryzyko rynkowe w większości banków UE.","u":5,"reg":"CRR część trzecia, tytuł IV, rozdz. 2–4 (metoda standardowa)","old":"","ot":"Wzór / agregacja","otc":"#4b4740","det":{"p":["Metoda standardowa dla ryzyka rynkowego w CRR to podejście „blokowe”: wymóg liczy się osobno dla instrumentów dłużnych, akcji, walut i towarów, a potem sumuje. Jest to obecnie główna metoda wymogu na ryzyko rynkowe w bankach UE, które nie mają zgody na model wewnętrzny.","Dla instrumentów dłużnych i akcji rozróżnia się ryzyko szczególne (związane z emitentem – wagi zależą od rodzaju emitenta, ratingu i terminu) oraz ryzyko ogólne (zmiana stóp lub całego rynku – dla obligacji metoda terminów zapadalności lub duration, z częściowym kompensowaniem pozycji w przedziałach). Dla walut wymóg to 8% sumy pozycji netto, jeśli przekracza ona 2% funduszy własnych; dla towarów – stawki od pozycji netto i brutto. Opcje obsługuje się metodami uproszczonymi lub delta-plus.","Metoda jest prosta, ale mało czuła na rzeczywiste ryzyko i słabo uznaje zabezpieczenia. Dlatego Bazylea zastąpiła ją w FRTB metodą opartą na wrażliwościach; w UE jej wdrożenie jako wymogu jest odroczone, a obecnie banki raportują FRTB obok."],"ex":["Akcje w metodzie standardowej",["Pozycja długa w akcjach 50 mln zł, krótka 30 mln zł.","Ryzyko szczególne: 8% × (50 + 30) = 6,4 mln zł.","Ryzyko ogólne: 8% × (50 − 30) = 1,6 mln zł.","Wymóg = 8,0 mln zł – krótka pozycja zmniejsza tylko część ogólną."]]},"par":[["—","wagi nadzorcze","Wymóg z tabel nadzorczych."]]},{"id":"frtbsa","d":"R","g":"Metody standardowe","n":"FRTB – metoda standardowa","o":"SBM, DRC, RRAO","k":"UL","s":"Nowa metoda standardowa Bazylei: wrażliwości (delta, vega, krzywizna) z wagami i korelacjami nadzorczymi, plus ryzyko defaultu i narzut rezydualny.","idea":"K = SBM(wrażliwości × wagi, korelacje) + DRC + RRAO","use":"Raportowanie w UE; wymóg po wejściu FRTB (w UE odroczone).","u":4,"reg":"CRR art. 325c–325az (alternatywna metoda standardowa); stosowanie jako wymogu odroczone","old":"","ot":"Wzór / agregacja","otc":"#4b4740","det":{"p":["FRTB (Fundamental Review of the Trading Book) to przebudowa reguł ryzyka rynkowego przez Komitet Bazylejski. Nowa metoda standardowa ma być bardziej czuła na ryzyko i służyć jako punkt odniesienia oraz dolny próg dla modeli wewnętrznych.","Główną częścią jest metoda wrażliwości (SBM). Bank liczy wrażliwości portfela na czynniki ryzyka w siedmiu klasach (stopy, spread kredytowy w trzech wersjach, akcje, towary, waluty): deltę, vegę i krzywiznę. Wrażliwości mnoży się przez nadzorcze wagi ryzyka i agreguje z nadzorczymi korelacjami – w trzech wariantach korelacji (niskie, średnie, wysokie), a wymóg to najwyższy wynik. Do tego dochodzi wymóg na ryzyko defaultu (DRC) dla pozycji kredytowych i akcyjnych oraz narzut na ryzyko rezydualne (RRAO) dla instrumentów egzotycznych.","W UE banki już raportują wyniki FRTB SA, ale stosowanie go jako wymogu kapitałowego zostało odroczone; obecnie obowiązuje dotychczasowa metoda standardowa z CRR."],"ex":["Ważona wrażliwość walutowa",["Portfel zyskuje 200 tys. zł przy wzroście kursu EUR/PLN o 1%.","Wrażliwość delta = 200 tys. / 0,01 = 20 mln zł.","Waga ryzyka FX = 15% → ważona wrażliwość = 3 mln zł.","Ważone wrażliwości z różnych walut agreguje się z korelacjami nadzorczymi."]]},"par":[["—","wagi i korelacje nadzorcze","Bank liczy wrażliwości; wagi i korelacje ustala regulacja."]]},{"id":"lda","d":"O","g":"","n":"LDA","o":"rozkład strat zagregowanych","k":"UL","s":"Roczna strata jako suma losowej liczby strat: częstość (Poisson, ujemny dwumianowy) i dotkliwość (lognormalny, Weibull, GPD); splot Monte Carlo lub Panjer.","idea":"L = Σᵢ₌₁ᴺ Xᵢ,  N ~ Poisson(λ),  X ~ LogN(μ, σ)","use":"AMA, kapitał wewnętrzny (Filar 2).","u":3,"reg":"","old":"","ot":"Kwantyl / rozkład","otc":"#8a4f8f","det":{"p":["LDA (Loss Distribution Approach) to aktuarialne podejście do strat operacyjnych. Roczna strata to suma losowej liczby zdarzeń, a każde zdarzenie ma losową wielkość. Modeluje się więc osobno częstość (ile zdarzeń w roku – zwykle Poisson lub ujemny dwumianowy) i dotkliwość (ile kosztuje jedno zdarzenie – lognormalny, Weibull, a w ogonie rozkład Pareto z teorii wartości ekstremalnych).","Rozkład straty rocznej powstaje ze splotu obu rozkładów: symulacją Monte Carlo (losujemy liczbę zdarzeń, potem ich wielkości, sumujemy – i tak sto tysięcy razy) albo rekurencją Panjera. Kapitał to kwantyl 99,9% straty rocznej, liczony osobno dla typów zdarzeń i linii biznesowych, a potem agregowany.","Charakterystyczne dla ryzyka operacyjnego: kwantyl zależy prawie wyłącznie od ogona dotkliwości, czyli od kilku bardzo dużych strat. Dlatego dane wewnętrzne uzupełnia się danymi zewnętrznymi (konsorcja strat) i scenariuszami eksperckimi."],"ex":["Rok strat operacyjnych",["Średnio 20 zdarzeń rocznie (Poisson), średnia strata 120 tys. zł (lognormalny z grubym ogonem).","Strata oczekiwana = 20 × 120 tys. = 2,4 mln zł.","Symulacja 100 000 lat: kwantyl 99,9% to np. ok. 25 mln zł.","W najgorszych latach jedno zdarzenie odpowiada za większość straty."]]},"par":[["λ","częstość strat","MLE dla rozkładu Poissona lub ujemnego dwumianowego."],["μ, σ","parametry dotkliwości","MLE z uwzględnieniem ucięcia na progu zbierania."],["ξ","ogon dotkliwości","Rozkład GPD powyżej progu."]]},{"id":"ama","d":"O","g":"","n":"AMA","o":"Bazylea II, do 2024","k":"UL","s":"Zaawansowane podejście pomiaru: dane wewnętrzne i zewnętrzne, scenariusze i czynniki otoczenia kontroli (BEICF).","idea":"kapitał = VaR 99,9% z LDA + korekty jakościowe","use":"Historycznie wymóg w dużych bankach.","u":1,"reg":"CRR art. 321–324 (uchylone przez CRR3)","old":"nieaktualna od 2025 r. (CRR3)","ot":"Kwantyl / rozkład","otc":"#8a4f8f","det":{"p":["AMA (Advanced Measurement Approach) była w Bazylei II najbardziej zaawansowaną metodą wymogu na ryzyko operacyjne. Bank mógł użyć własnego modelu – w praktyce prawie zawsze LDA – pod warunkiem spełnienia rozbudowanych wymogów jakościowych i ilościowych.","Model AMA musiał łączyć cztery elementy: dane o stratach wewnętrznych (zwykle co najmniej 5 lat), dane zewnętrzne (by uchwycić rzadkie, duże zdarzenia z innych banków), analizę scenariuszową (oceny ekspertów) oraz czynniki otoczenia biznesowego i kontroli wewnętrznej (BEICF), które korygowały wynik o jakość kontroli. Kapitał odpowiadał kwantylowi 99,9% straty rocznej.","Krytyka dotyczyła dużej zmienności wyników i trudności w porównywaniu banków. CRR3 zastąpiła AMA metodą standardową (SMA) od 2025 roku, ale modele LDA nadal służą w ICAAP do kapitału wewnętrznego."],"ex":["Cztery źródła w jednym modelu",["Dane wewnętrzne: rozkład częstych, małych strat.","Dane zewnętrzne i scenariusze: ogon – np. „błąd systemu płatności, raz na 25 lat, 40 mln zł”.","BEICF: słabe wyniki audytu IT → korekta +10% dla tej kategorii.","Wynik: kwantyl 99,9% z połączonego rozkładu = wymóg kapitałowy."]]},"par":[["λ, μ, σ","częstość i dotkliwość","Jak w LDA."],["w","wagi źródeł danych","Łączenie danych wewnętrznych, zewnętrznych i scenariuszy."]]},{"id":"sma","d":"O","g":"","n":"SMA / BIC","o":"CRR3","k":"UL","s":"Podejście standardowe: składnik wskaźnika biznesowego (BIC) przemnożony przez mnożnik strat (w UE ILM = 1).","idea":"K = BIC(BI) × ILM","use":"Wymóg na ryzyko operacyjne od 2025 r.","u":5,"reg":"CRR3 – część trzecia, tytuł III (składnik wskaźnika biznesowego)","old":"","ot":"Wzór / agregacja","otc":"#4b4740","det":{"p":["SMA (Standardised Measurement Approach), wprowadzona w CRR3 od 2025 roku, jest jedyną metodą wymogu na ryzyko operacyjne w UE. Opiera się na założeniu, że ryzyko operacyjne rośnie z wielkością i złożonością działalności.","Punktem wyjścia jest wskaźnik biznesowy (BI) – suma trzech składników z rachunku wyników: odsetkowego (z dywidendami), usługowego (prowizje i pozostałe) i finansowego (wynik na instrumentach). Składnik wskaźnika biznesowego (BIC) to BI przemnożony przez rosnące krańcowe stawki: 12% do 1 mld euro, 15% od 1 do 30 mld, 18% powyżej.","W wersji bazylejskiej BIC mnożono jeszcze przez mnożnik strat wewnętrznych (ILM), zależny od historii strat banku. UE ustaliła ILM = 1 – więc wymóg zależy tylko od wielkości działalności, a nie od historii strat."],"ex":["Wymóg z rachunku wyników",["Wskaźnik biznesowy banku: 900 mln euro.","BIC = 12% × 900 mln = 108 mln euro.","ILM = 1 → wymóg = 108 mln euro.","RWA na ryzyko operacyjne = 12,5 × 108 = 1,35 mld euro."]]},"par":[["—","współczynniki nadzorcze","Składnik wskaźnika biznesowego ze stawek nadzorczych; w UE mnożnik strat = 1."]]},{"id":"bia","d":"O","g":"","n":"BIA, TSA, ASA","o":"Bazylea II","k":"UL","s":"Historyczne metody: odsetek dochodu (15%) albo stawki 12–18% według linii biznesowych.","idea":"K = 15% × średni dochód z 3 lat","use":"Do CRR3; porównania.","u":1,"reg":"CRR art. 315–320 (uchylone przez CRR3)","old":"nieaktualne od 2025 r. (CRR3)","ot":"Wzór / agregacja","otc":"#4b4740","det":{"p":["Metody podstawowe Bazylei II zakładały, że ryzyko operacyjne jest proporcjonalne do dochodów. Metoda wskaźnika bazowego (BIA): 15% średniego wyniku z ostatnich trzech lat (lata z ujemnym wynikiem pomija się).","Metoda standardowa (TSA) dzieliła działalność na osiem linii biznesowych – bankowość detaliczna, komercyjna, inwestycyjna, płatności, zarządzanie aktywami… – z różnymi stawkami od 12% do 18%, bo uznawano, że np. handel jest bardziej ryzykowny niż zarządzanie aktywami. Alternatywna metoda standardowa (ASA) dla bankowości detalicznej i komercyjnej zastępowała dochód wielkością kredytów (3,5% portfela), żeby wysokomarżowe banki nie były karane.","Metody te obowiązywały do końca 2024 roku. Warto je znać, bo pokazują ewolucję: od prostej proporcji do dochodu, przez modele (AMA), z powrotem do standardu (SMA)."],"ex":["Wymóg w BIA",["Wynik z ostatnich trzech lat: 550, 600, 650 mln zł → średnia 600 mln zł.","Wymóg = 15% × 600 mln = 90 mln zł.","RWA = 12,5 × 90 = 1,125 mld zł.","Lepszy wynik oznaczał wyższy wymóg – niezależnie od jakości kontroli."]]},"par":[["—","stawki nadzorcze","15% albo 12–18% według linii – nadzorcze."]]},{"id":"scen","d":"O","g":"","n":"Analiza scenariuszowa","o":"oceny eksperckie","k":"S","s":"Eksperci oceniają częstość i dotkliwość rzadkich, dużych zdarzeń, których brak w danych.","idea":"scenariusz → (częstość, strata typowa, strata skrajna)","use":"Uzupełnienie LDA, ICAAP.","u":4,"reg":"","old":"","ot":"Scenariusz / ekspert","otc":"#a8443a","det":{"p":["Analiza scenariuszowa uzupełnia dane o zdarzenia rzadkie i duże, których bank nigdy nie doświadczył, ale które mogą się zdarzyć: awaria centrum danych, poważny cyberatak, systemowy błąd w produkcie, nadużycie wewnętrzne na dużą skalę.","Ekspertów z biznesu, IT, ryzyka i zgodności prosi się o opis scenariusza i oszacowanie jego częstości oraz strat: typowej i skrajnej (np. raz na 100 lat). Dobre warsztaty mają strukturę: przegląd danych zewnętrznych podobnych zdarzeń, kotwiczenie na faktach, kwestionowanie ocen, dokumentowanie założeń. Ludzie mają skłonność do zaniżania ogonów – stąd potrzeba moderacji i porównań.","Wyniki zasilają model LDA (jako dodatkowe punkty ogona), kapitał wewnętrzny w ICAAP, ale przede wszystkim zarządzanie: wskazują, gdzie wzmocnić kontrole i plany ciągłości działania."],"ex":["Awaria centrum danych",["Częstość: raz na 20 lat (5% rocznie).","Strata typowa: 5 mln zł (dwa dni przestoju, kary, nadgodziny).","Strata skrajna (raz na 100 lat): 40 mln zł – utrata danych, roszczenia klientów.","Te trzy liczby wyznaczają rozkład dotkliwości scenariusza w modelu."]]},"par":[["f","częstość zdarzenia","Ocena ekspertów kotwiczona danymi zewnętrznymi."],["L","strata typowa i skrajna","Ocena ekspertów."]]},{"id":"bayes","d":"O","g":"","n":"Sieci bayesowskie","o":"modele przyczynowe","k":"S","s":"Graf przyczyn i skutków zdarzeń operacyjnych; łączy dane z wiedzą ekspercką.","idea":"P(strata | przyczyny) z grafu zależności","use":"Ryzyko IT, procesy, scenariusze.","u":1,"reg":"","old":"","ot":"Scenariusz / ekspert","otc":"#a8443a","det":{"p":["Sieć bayesowska to graf: węzły to zmienne (np. stan aktualizacji systemu, obciążenie pracowników, wystąpienie incydentu, wielkość straty), a strzałki to zależności przyczynowe. Każdy węzeł ma tablicę prawdopodobieństw warunkowych – częściowo z danych, częściowo z ocen ekspertów.","Siła tego podejścia polega na dwukierunkowym wnioskowaniu. Można pytać „co się stanie, jeśli” – jak zmieni się prawdopodobieństwo straty, gdy poprawimy kontrolę. Można też pytać wstecz: zaobserwowaliśmy incydent – jaka była najbardziej prawdopodobna przyczyna. Dzięki temu sieci łączą pomiar ryzyka z zarządzaniem przyczynami.","Stosuje się je głównie w ryzyku IT i cyberbezpieczeństwie, procesach i scenariuszach, gdzie danych jest mało, a wiedza ekspercka duża."],"ex":["Od przyczyny do skutku i z powrotem",["P(brak aktualizacji systemu) = 30%; P(awaria | brak aktualizacji) = 8%, P(awaria | aktualny) = 2%.","P(awaria) = 0,3 × 8% + 0,7 × 2% = 3,8%.","Doszło do awarii: P(brak aktualizacji | awaria) = 2,4% / 3,8% ≈ 63%.","Aktualizacje obniżyłyby ryzyko awarii z 3,8% do 2%."]]},"par":[["P(·|·)","prawdopodobieństwa warunkowe","Z danych i ocen ekspertów, aktualizowane po nowych obserwacjach."]]},{"id":"rep","d":"O","g":"","n":"Ryzyko reputacji","o":"scenariusze, sentyment, zdarzenia","k":"S","s":"Utrata zaufania klientów, rynku lub nadzoru przekłada się na odpływ depozytów, utratę klientów, droższe finansowanie i spadek kursu akcji.","idea":"strata = odpływ depozytów + utracony wynik + koszt finansowania (scenariusz)","use":"Filar 2, ICAAP, stres testy płynności.","u":2,"reg":"","old":"","ot":"Scenariusz / ekspert","otc":"#a8443a","det":{"p":["Ryzyko reputacji to ryzyko, że utrata zaufania klientów, kontrahentów, inwestorów lub nadzoru przełoży się na straty. Rzadko jest źródłem straty samo w sobie – częściej wzmacnia inne ryzyka: wywołuje odpływ depozytów, odejście klientów, wzrost kosztu finansowania, spadek kursu akcji czy większą uwagę nadzoru.","Modeluje się je głównie scenariuszowo: zdarzenie wyzwalające (wyciek danych, afera sprzedażowa, kary, ryzyko prawne, kryzys w grupie) → reakcja klientów i rynku → skutki finansowe w wyniku, płynności i kapitale. Uzupełniają to wskaźniki ryzyka (reklamacje, NPS, liczba negatywnych publikacji), analiza sentymentu w mediach i mediach społecznościowych oraz badania zdarzeń (event study) – jak kurs akcji banków reagował na podobne zdarzenia.","Wynik trafia do Filaru 2 (ocena ryzyka i ewentualny narzut lub bufor), do stres testów płynności i do planów zarządzania kryzysowego. Przypadek Silicon Valley Bank pokazał, jak szybko zła informacja może zamienić się w odpływ depozytów."],"ex":["Scenariusz wycieku danych",["Zdarzenie: wyciek danych klientów i szeroka kampania w mediach.","Reakcja: odpływ 3% depozytów detalicznych w miesiąc, odejście 2% klientów w ciągu roku.","Skutki: utracony wynik odsetkowy i prowizyjny 40 mln zł, droższe finansowanie zastępcze 15 mln zł.","Łącznie 55 mln zł – podstawa oceny kapitału wewnętrznego na ryzyko reputacji."]]},"par":[["o","odpływ depozytów i klientów","Scenariuszowo – z analogii i danych z podobnych zdarzeń."]]},{"id":"lcr","d":"L","g":"","n":"LCR","o":"wskaźnik pokrycia wypływów","k":"P","s":"Aktywa płynne wysokiej jakości wobec wypływów netto w 30-dniowym stresie.","idea":"LCR = HQLA / wypływy netto (30 dni) ≥ 100%","use":"Wymóg nadzorczy, limity.","u":5,"reg":"CRR art. 412; rozporządzenie delegowane (UE) 2015/61","old":"","ot":"Wzór / agregacja","otc":"#4b4740","det":{"p":["LCR (Liquidity Coverage Ratio) to wskaźnik krótkoterminowej odporności płynnościowej, wprowadzony po kryzysie 2008 roku. Bank musi mieć tyle aktywów płynnych wysokiej jakości (HQLA), żeby przetrwać 30 dni ostrego stresu – bez pomocy banku centralnego.","Licznik to HQLA: gotówka, rezerwy w banku centralnym, obligacje skarbowe (poziom 1), a w ograniczonym zakresie inne papiery z redukcjami wartości (poziomy 2A i 2B). Mianownik to wypływy netto w scenariuszu nadzorczym: każdą kategorię pasywów mnoży się przez współczynnik odpływu (np. 5–10% dla stabilnych depozytów detalicznych, 40% dla operacyjnych depozytów firm, 100% dla niezabezpieczonego finansowania hurtowego od instytucji finansowych), od czego odejmuje się wpływy, ale najwyżej do 75% wypływów.","Wymóg to co najmniej 100%. Modele depozytów i ich klasyfikacja wprost wpływają na wynik."],"ex":["Czy bank przetrwa 30 dni",["HQLA: 30 mld zł.","Wypływy w scenariuszu: 40 mld zł; wpływy: 15 mld zł (poniżej limitu 75% × 40 = 30).","Wypływy netto = 25 mld zł → LCR = 30 / 25 = 120%.","Przeklasyfikowanie 10 mld depozytów z 5% na 10% odpływu obniża LCR do ok. 118%."]]},"par":[["o","współczynniki odpływu","Nadzorcze; bank klasyfikuje depozyty (stabilne, operacyjne)."]]},{"id":"nsfr","d":"L","g":"","n":"NSFR","o":"stabilne finansowanie","k":"P","s":"Dostępne stabilne finansowanie wobec wymaganego w horyzoncie roku.","idea":"NSFR = ASF / RSF ≥ 100%","use":"Struktura finansowania.","u":5,"reg":"CRR art. 413 i 428a–428az","old":"","ot":"Wzór / agregacja","otc":"#4b4740","det":{"p":["NSFR (Net Stable Funding Ratio) uzupełnia LCR w horyzoncie rocznym. Pyta o strukturę finansowania: czy aktywa długoterminowe i mało płynne są finansowane stabilnymi źródłami, a nie krótkim finansowaniem hurtowym, które może zniknąć.","Dostępne stabilne finansowanie (ASF) to pasywa ważone stabilnością: kapitał i długie finansowanie 100%, stabilne depozyty detaliczne 95%, mniej stabilne 90%, depozyty firm 50%, krótkie finansowanie od instytucji finansowych 0%. Wymagane stabilne finansowanie (RSF) to aktywa ważone ich płynnością: gotówka 0%, obligacje skarbowe 5%, kredyty hipoteczne 65%, inne kredyty 85%, aktywa obciążone i niepłynne 100%.","Wymóg to NSFR co najmniej 100%. Wskaźnik ogranicza model biznesowy oparty na finansowaniu długich kredytów krótkim pieniądzem z rynku."],"ex":["Stabilność finansowania",["ASF: kapitał 10 + depozyty detaliczne 60 × 95% + depozyty firm 40 × 50% ≈ 87 mld zł (plus inne → 90).","RSF: kredyty hipoteczne 50 × 65% + inne kredyty 40 × 85% + obligacje 20 × 5% ≈ 67,5 (plus inne → 75).","NSFR = 90 / 75 = 120%.","Zastąpienie 10 mld depozytów detalicznych finansowaniem z rynku obniżyłoby ASF o 9,5 mld."]]},"par":[["—","współczynniki nadzorcze","Wagi ASF i RSF są nadzorcze."]]},{"id":"lgap","d":"L","g":"","n":"Luka płynności","o":"kontraktowa i urealniona","k":"P","s":"Przepływy w przedziałach czasu, urealnione o zachowania klientów; horyzont przetrwania.","idea":"luka skumulowana_k = Σ (wpływy − wypływy)","use":"ILAAP, plan awaryjny.","u":5,"reg":"","old":"","ot":"Parametr","otc":"#7a8b3a","det":{"p":["Luka płynności zestawia przyszłe wpływy i wypływy środków w przedziałach czasu: 1 dzień, tydzień, miesiąc, kwartał, rok. Luka kontraktowa bierze terminy z umów; luka urealniona koryguje je o zachowania klientów – osad depozytów, przedpłaty, wykorzystanie limitów, odnawialność finansowania.","Skumulowana luka pokazuje, w którym momencie bank potrzebowałby dodatkowego finansowania. Porównując ją z buforem płynności (aktywa możliwe do szybkiej sprzedaży lub zastawu), wyznacza się horyzont przetrwania – jak długo bank wytrzyma bez dostępu do nowego finansowania.","Luka płynności to podstawowe narzędzie wewnętrznego zarządzania płynnością, limitów i planu awaryjnego; razem ze stres testami tworzy trzon ILAAP."],"ex":["Horyzont przetrwania",["Bufor płynności: 10 mld zł.","Luka netto: dni 1–7: −3 mld; dni 8–30: −4 mld; dni 31–90: −5 mld.","Skumulowana luka: −3, −7, −12 mld zł.","Bufor wystarcza na pierwsze 30 dni, ale nie do 90 – horyzont przetrwania ok. 1–3 miesięcy."]]},"par":[["osad, odpływy","parametry behawioralne","Z modeli depozytów, limitów i odnawiania finansowania."]]},{"id":"lst","d":"L","g":"","n":"Stres testy płynności, ILAAP","o":"scenariusze odpływów","k":"S","s":"Scenariusze odpływu depozytów, zamknięcia rynków i utraty finansowania; ocena bufora.","idea":"horyzont przetrwania w scenariuszu","use":"ILAAP, limity, plan awaryjny.","u":5,"reg":"","old":"","ot":"Scenariusz / ekspert","otc":"#a8443a","det":{"p":["Testy warunków skrajnych płynności sprawdzają, czy bank przetrwa scenariusze gorsze niż w LCR i trwające dłużej. Typowe scenariusze to: specyficzny dla banku (utrata zaufania, odpływ depozytów, obniżka ratingu), rynkowy (zamknięcie rynku międzybankowego, spadek cen obligacji, wzrost depozytów zabezpieczających) i łączny.","Dla każdego scenariusza zakłada się tempo odpływów w czasie, utratę wartości aktywów płynnych, wykorzystanie limitów przez klientów i reakcję kontrahentów. Wynikiem jest horyzont przetrwania i luka do pokrycia działaniami z planu awaryjnego (sprzedaż papierów, repo, ograniczenie akcji kredytowej).","Stres testy płynności są częścią ILAAP – wewnętrznej oceny adekwatności płynności – i podstawą do ustalenia limitów oraz wielkości bufora. Doświadczenia 2023 roku (Silicon Valley Bank) pokazały, że cyfrowe odpływy mogą być znacznie szybsze niż zakładano."],"ex":["Odpływ w tydzień",["Depozyty detaliczne: 60 mld zł; scenariusz: odpływ 10% w pierwszym tygodniu = 6 mld zł.","Dodatkowo: wygasa 2 mld finansowania hurtowego.","Bufor HQLA: 9 mld zł → po tygodniu zostaje 1 mld.","Bank musi uruchomić plan awaryjny już w drugim tygodniu."]]},"par":[["oₛ","odpływy w scenariuszu","Założenia scenariusza – historia, analogie, ocena ekspercka."]]},{"id":"agg","d":"C","g":"","n":"Agregacja ryzyk","o":"suma, korelacje, kopuły","k":"UL","s":"Łączenie kapitału z różnych ryzyk; od prostej sumy, przez macierz korelacji, po kopuły i symulację wspólną.","idea":"EC = √(e′ R e)  lub  symulacja z kopułą","use":"ICAAP, kapitał wewnętrzny.","u":4,"reg":"","old":"","ot":"Kwantyl / rozkład","otc":"#8a4f8f","det":{"p":["Kapitał na poszczególne ryzyka liczy się zwykle osobnymi modelami: kredytowe, rynkowe, operacyjne, stopy procentowej. W ICAAP trzeba je połączyć w jeden kapitał wewnętrzny banku. Najprostsza i najbardziej ostrożna metoda to suma – zakłada, że wszystkie najgorsze scenariusze zdarzają się jednocześnie.","Kolejny poziom to macierz korelacji (agregacja wariancji–kowariancji): kapitał całkowity to pierwiastek z formy kwadratowej, jak przy odchyleniu portfela. Korelacje są zwykle ustalane eksperckimi ocenami lub z danych o stratach. Najbardziej zaawansowane podejścia łączą pełne rozkłady strat kopułami albo symulują wspólne scenariusze makro dla wszystkich ryzyk (podejście bottom-up).","Efekt dywersyfikacji bywa znaczny, ale nadzór podchodzi do niego ostrożnie: w kryzysie korelacje rosną, a wiele banków w ICAAP stosuje prostą sumę lub małe korzyści dywersyfikacji."],"ex":["Suma kontra korelacje",["Kapitał: kredytowe 800, rynkowe 200, operacyjne 150 mln zł → suma 1150.","Korelacje: kredytowe–rynkowe 0,5; pozostałe pary 0,2.","Kapitał zagregowany = √(800² + 200² + 150² + 2 × 0,5 × 800 × 200 + 2 × 0,2 × 800 × 150 + 2 × 0,2 × 200 × 150) ≈ 961 mln zł.","Korzyść z dywersyfikacji: ok. 16%."]]},"par":[["ρᵢⱼ","korelacje między ryzykami","Ekspercko albo z danych o stratach – kluczowe dla dywersyfikacji."]]},{"id":"raroc","d":"C","g":"","n":"RAROC, EVA, SVA","o":"rentowność skorygowana o ryzyko","k":"UL","s":"Dochód po kosztach i stracie oczekiwanej odniesiony do kapitału ekonomicznego.","idea":"RAROC = (dochód − koszty − EL) / kapitał ekonomiczny","use":"Ceny, ocena jednostek, decyzje.","u":3,"reg":"","old":"","ot":"Wzór / agregacja","otc":"#4b4740","det":{"p":["RAROC (Risk-Adjusted Return on Capital) mierzy rentowność działalności po uwzględnieniu ryzyka. W liczniku jest dochód pomniejszony o koszty, stratę oczekiwaną (koszt ryzyka) i zwykle koszt finansowania; w mianowniku – kapitał ekonomiczny potrzebny na stratę nieoczekiwaną.","Pozwala porównywać produkty i jednostki o różnym ryzyku: kredyt z wysoką marżą, ale dużym kapitałem, może być mniej opłacalny niż bezpieczny kredyt z niską marżą. RAROC porównuje się ze stopą graniczną (hurdle rate), odpowiadającą kosztowi kapitału akcjonariuszy. Pokrewne miary to EVA (zysk ekonomiczny: wynik minus koszt kapitału) i SVA (wartość dla akcjonariuszy).","RAROC stosuje się do wyceny kredytów (jaka marża jest potrzebna), oceny relacji z klientem, wynagradzania i alokacji kapitału między linie biznesowe."],"ex":["Czy kredyt tworzy wartość",["Dochód 12 mln zł, koszty 4 mln, strata oczekiwana 2 mln.","Kapitał ekonomiczny: 40 mln zł.","RAROC = (12 − 4 − 2) / 40 = 15%.","Przy koszcie kapitału 12%: EVA = 6 − 0,12 × 40 = 1,2 mln zł – kredyt tworzy wartość."]]},"par":[["EC, EL","kapitał i strata oczekiwana","Z modeli ryzyka."],["rₕ","stopa graniczna","Koszt kapitału – z modelu CAPM albo decyzji zarządu."]]},{"id":"p2","d":"C","g":"","n":"Modele Filaru 2","o":"koncentracja, IRRBB, biznesowe","k":"UL","s":"Kapitał na ryzyka poza Filarem 1 albo niedoszacowane w Filarze 1.","idea":"P2R = Σ narzutów (ICAAP, SREP)","use":"ICAAP, SREP.","u":5,"reg":"CRD art. 73, 97 i 104; Prawo bankowe art. 128; wytyczne EBA w sprawie SREP","old":"","ot":"Kwantyl / rozkład","otc":"#8a4f8f","det":{"p":["Filar 1 pokrywa ryzyka kredytowe, rynkowe i operacyjne według wzorów regulacyjnych. Ale bank ma też ryzyka, których Filar 1 nie obejmuje albo obejmuje niedostatecznie: koncentracji, stopy procentowej w księdze bankowej, biznesowe i strategiczne, reputacyjne, modeli, a także ryzyko kredytowe niedoszacowane przez metodę standardową.","W ICAAP bank sam ocenia te ryzyka i wylicza kapitał wewnętrzny – często własnymi modelami: narzut na koncentrację (HHI, granularność), kapitał na IRRBB (z ΔEVE lub ΔNII w scenariuszach), na ryzyko biznesowe (zmienność wyniku), na ryzyko modeli (bufory z analizy wrażliwości). Nadzór w procesie SREP ocenia ICAAP i ustala wymóg Filaru 2 (P2R) oraz zalecenie (P2G) wynikające ze stres testów.","P2R jest obowiązkowy i co najmniej w 56,25% musi być pokryty kapitałem CET1, P2G – oczekiwany."],"ex":["Narzuty ponad Filar 1",["Koncentracja branżowa: +0,6 pp RWA; IRRBB: +0,5 pp; ryzyko biznesowe: +0,2 pp.","Ocena banku w ICAAP: 1,3 pp ponad wymóg 8%.","Nadzór w SREP ustala P2R = 1,5 pp.","Łączny wymóg (bez buforów): 9,5% RWA."]]},"par":[["n","narzuty na ryzyka Filaru 2","Z modeli wewnętrznych i ocen; ostatecznie P2R ustala nadzór."]]},{"id":"biz","d":"C","g":"","n":"Ryzyko biznesowe i strategiczne","o":"earnings at risk, zmienność wyniku","k":"UL","s":"Ryzyko, że wynik spadnie z powodu zmian otoczenia, konkurencji, wolumenów, marż lub błędnej strategii – niezależnie od strat kredytowych i rynkowych.","idea":"EaR = wynik oczekiwany − kwantyl wyniku; kapitał ≈ EaR × okres odbudowy","use":"Filar 2, ICAAP, planowanie strategiczne.","u":3,"reg":"","old":"","ot":"Kwantyl / rozkład","otc":"#8a4f8f","det":{"p":["Ryzyko biznesowe to ryzyko spadku wyniku z przyczyn, które nie są stratami kredytowymi, rynkowymi ani operacyjnymi: spadku wolumenów, presji na marże i prowizje, zmian regulacyjnych (np. limitów opłat), wejścia konkurencji, zmian zachowań klientów. Ryzyko strategiczne dotyczy błędnych lub źle wdrożonych decyzji strategicznych – przejęć, nowych linii biznesowych, inwestycji technologicznych.","Najczęstszą miarą jest earnings at risk (EaR): o ile wynik w złym roku może być niższy od oczekiwanego. Szacuje się go z historycznej zmienności przychodów i kosztów (po wyłączeniu strat z innych ryzyk), modelami opartymi na wrażliwości przychodów na czynniki makro albo scenariuszowo – dla kluczowych założeń planu. Kapitał wylicza się zwykle jako stratę wyniku przez okres, w którym bank może dostosować koszty i model biznesowy.","Wynik trafia do kapitału wewnętrznego w ICAAP (Filar 2), a nadzór ocenia go w SREP razem z analizą modelu biznesowego (BMA): czy model jest rentowny i trwały w horyzoncie kilku lat."],"ex":["Kapitał na spadek wyniku",["Oczekiwany wynik przed odpisami: 1 000 mln zł; z historii i scenariuszy kwantyl 99% wyniku: 760 mln zł.","EaR = 1 000 − 760 = 240 mln zł w roku.","Bank potrzebuje 1,5 roku na dostosowanie kosztów → kapitał ≈ 240 × 1,5 = 360 mln zł.","Po uwzględnieniu dywersyfikacji z innymi ryzykami w ICAAP – mniej."]]},"par":[["σ","zmienność wyniku","Z historii przychodów i kosztów po wyłączeniu strat z innych ryzyk."],["T","okres dostosowania","Założenie – czas na odbudowę modelu biznesowego."]]},{"id":"sens","d":"S","g":"","n":"Analiza wrażliwości","o":"jeden czynnik naraz","k":"S","s":"Zmiana jednego czynnika (stopy, kurs, PD) przy pozostałych bez zmian.","idea":"ΔV = V(x + Δxᵢ) − V(x)","use":"Szybka ocena podatności.","u":5,"reg":"","old":"","ot":"Scenariusz / ekspert","otc":"#a8443a","det":{"p":["Analiza wrażliwości to najprostszy test warunków skrajnych: zmienia się jeden czynnik ryzyka, a pozostałe zostają bez zmian, i sprawdza, jak bardzo zmienia się wynik, wartość lub kapitał. Typowe czynniki: stopy procentowe, kursy walut, ceny akcji, PD, LGD, ceny nieruchomości, odpływ depozytów.","Jej siłą jest przejrzystość – od razu widać, na co bank jest najbardziej wrażliwy i w jakiej skali. Pozwala też ustawić limity i porównywać okresy. Słabością jest brak spójności: w prawdziwym kryzysie czynniki zmieniają się razem (spadek PKB, wzrost bezrobocia, spadek cen nieruchomości i wzrost PD jednocześnie), a ich łączny efekt bywa większy niż suma pojedynczych.","Dlatego wrażliwości są pierwszym krokiem – do zrozumienia profilu ryzyka – a pełne scenariusze makro i odwrócone stres testy budują na nich obraz łącznego stresu."],"ex":["Jeden czynnik naraz",["Stopy +100 pb: ΔEVE = −35 mln zł, ΔNII = +20 mln zł.","PD × 1,5 w całym portfelu: ECL +45 mln zł.","Kurs CHF +20%: RWA +3%, ECL kredytów walutowych +12 mln zł.","Każdy wynik osobno – łączny efekt wymaga scenariusza."]]},"par":[["Δx","wielkość szoku","Założenie – z historii albo progów istotności."]]},{"id":"macro","d":"S","g":"","n":"Scenariusze makro i modele satelitarne","o":"bazowy, niekorzystny","k":"S","s":"Ścieżki PKB, stóp, bezrobocia i cen przenoszone modelami satelitarnymi na PD, LGD, NII i kapitał.","idea":"PD_s,t = f(makro_s,t)","use":"Stres testy, FLI, plan kapitałowy.","u":5,"reg":"","old":"","ot":"Prognoza","otc":"#3f8a77","det":{"p":["Stres test makroekonomiczny zaczyna się od spójnej historii: co dzieje się w gospodarce w scenariuszu bazowym i niekorzystnym, zwykle na 3 lata. Scenariusz to ścieżki PKB, bezrobocia, inflacji, stóp procentowych, kursów, cen nieruchomości i akcji.","Modele satelitarne przenoszą te zmienne na parametry banku: PD i LGD (a stąd odpisy i RWA), wynik odsetkowy (przez stopy i wolumeny), wynik prowizyjny, wycenę papierów. Na końcu liczy się wynik, kapitał i wskaźniki w każdym roku scenariusza. Dobre modele satelitarne są proste, stabilne i mają sens ekonomiczny – znak i siła zależności muszą dać się wytłumaczyć.","Te same modele wykorzystuje się w MSSF 9 (FLI), w planowaniu finansowym i kapitałowym oraz w stres testach nadzorczych. Ważne jest, by scenariusz był dotkliwy, ale wiarygodny."],"ex":["Recesja w trzech krokach",["Scenariusz: PKB −3%, bezrobocie +4 pp, ceny mieszkań −15%.","Model satelitarny: PD portfela rośnie z 1,5% do 3,2%, LGD hipotek z 20% do 28%.","ECL rośnie o 60%, RWA w IRB o 12%.","CET1 spada z 15% do 12,3% w drugim roku."]]},"par":[["βˢ","współczynniki modeli satelitarnych","Regresja szeregów czasowych lub panelowa."]]},{"id":"rst","d":"S","g":"","n":"Reverse stress testing","o":"odwrócony test","k":"S","s":"Szukanie scenariusza, który doprowadza bank do naruszenia wymogów albo niewypłacalności.","idea":"min ‖scenariusz‖ przy CET1(scenariusz) = próg","use":"ICAAP, plan naprawy.","u":4,"reg":"","old":"","ot":"Scenariusz / ekspert","otc":"#a8443a","det":{"p":["Zwykły stres test pyta: co się stanie z bankiem w danym scenariuszu. Odwrócony stres test pyta odwrotnie: jaki scenariusz doprowadziłby bank do upadku albo naruszenia wymogów – i czy jest on bardziej prawdopodobny, niż sądzimy.","Zaczyna się od wyniku: np. CET1 spada do poziomu wymogu, LCR poniżej 100%, utrata płynności w tydzień. Następnie szuka się kombinacji czynników, która do tego prowadzi – analitycznie (jak duży musi być każdy szok) lub w warsztatach eksperckich, które pytają o słabe punkty modelu biznesowego, koncentracje i zależności. Często okazuje się, że do upadku wystarczy kombinacja kilku umiarkowanych, ale skorelowanych zdarzeń.","Odwrócone stres testy są wymagane w ICAAP i planowaniu naprawy; pomagają ustalić wskaźniki wczesnego ostrzegania i progi planu naprawy."],"ex":["Co łamie bank",["CET1 dziś 15%, wymóg łączny z buforami 10,5% → bufor 4,5 pp.","Sam wzrost PD łamie bank dopiero przy PD × 4.","Ale PD × 2,5, spadek stóp o 300 pb (niższy wynik) i odpływ 5% depozytów łącznie wystarczą.","Taki scenariusz jest wiarygodny – bank wzmacnia bufor i plan naprawy."]]},"par":[["s*","scenariusz łamiący bank","Szukany odwrotnie – wynik analizy, nie estymacji."]]},{"id":"eba","d":"S","g":"","n":"Stres testy nadzorcze","o":"EBA / KNF","k":"S","s":"Wspólna metodyka i scenariusze nadzorcze, zwykle przy statycznym bilansie.","idea":"CET1 w scenariuszu niekorzystnym (3 lata)","use":"SREP, P2G.","u":3,"reg":"Rozporządzenie (UE) 1093/2010 (EBA); metodyka stres testów EBA","old":"","ot":"Scenariusz / ekspert","otc":"#a8443a","det":{"p":["Stres testy nadzorcze prowadzi EBA (dla największych banków UE, co dwa lata) oraz krajowe nadzory, w Polsce KNF. Wszystkie banki stosują ten sam scenariusz makro i wspólną metodykę, co pozwala porównać ich odporność.","Metodyka EBA zakłada zwykle statyczny bilans: bank nie może poprawiać wyniku zmianą struktury ani wzrostem biznesu. Określa, jak liczyć straty kredytowe (z przejściami między koszykami), wynik odsetkowy (z ograniczeniami wzrostu marży), straty rynkowe, ryzyko operacyjne i prowizje. Testy obejmują zwykle 3 lata scenariusza bazowego i niekorzystnego.","Wynikiem jest spadek CET1 w scenariuszu niekorzystnym. Nadzór wykorzystuje go w SREP – m.in. do ustalenia zalecenia P2G, czyli dodatkowego bufora kapitału, który bank powinien utrzymywać."],"ex":["Od testu do zalecenia",["CET1 na start: 16%.","Scenariusz niekorzystny: najniższy CET1 w trzecim roku – 11%.","Spadek o 5 pp, wyraźnie więcej niż u porównywalnych banków.","Nadzór ustala P2G na poziomie 1,5% – oczekiwany bufor ponad wymogi."]]},"par":[["—","scenariusz i metodyka nadzorcza","Scenariusz jest zadany; bank stosuje własne modele satelitarne."]]},{"id":"plan","d":"S","g":"","n":"Plan kapitałowy i plan naprawy","o":"wskaźniki i opcje naprawy","k":"S","s":"Prognoza kapitału w scenariuszach oraz wskaźniki i działania przywracające kapitał i płynność.","idea":"CET1_t = CET1_t−1 + zysk − dywidenda − ΔRWA·wymóg","use":"ICAAP, ustawa o BFG.","u":5,"reg":"Ustawa o BFG (plany naprawy); BRRD","old":"","ot":"Prognoza","otc":"#3f8a77","det":{"p":["Plan kapitałowy pokazuje, jak będzie się zmieniał kapitał i wymogi w najbliższych latach – w scenariuszu bazowym i w stresie. Uwzględnia zysk, dywidendy, wzrost RWA z planu biznesowego, zmiany regulacyjne (np. CRR3, output floor) i emisje instrumentów kapitałowych.","Plan naprawy idzie o krok dalej: opisuje, co bank zrobi, gdy sytuacja się pogorszy. Zawiera wskaźniki naprawy (kapitał, płynność, rentowność, jakość aktywów) z progami ostrzegawczymi i progami uruchomienia oraz katalog opcji naprawczych: wstrzymanie dywidendy, emisja akcji, sprzedaż portfeli lub spółek, ograniczenie akcji kredytowej, pozyskanie finansowania. Każdą opcję ocenia się pod kątem wpływu, czasu realizacji i wykonalności w stresie.","W Polsce plany naprawy regulują ustawa o BFG i rozporządzenia; nadzór ocenia je co roku."],"ex":["Kapitał za rok",["CET1 = 10 mld zł, RWA = 80 mld zł → 12,5%.","Zysk 1,2 mld zł, dywidenda 50% → CET1 = 10,6 mld zł.","RWA rośnie o 5% do 84 mld zł → CET1 = 12,6%.","W stresie: strata 0,8 mld i brak dywidendy → 9,2 / 84 ≈ 11,0% – blisko progu planu naprawy."]]},"par":[["Π, ΔRWA","projekcje zysku i RWA","Z planu finansowego i modeli – założenia."]]},{"id":"mrq","d":"M","g":"","n":"Kwantyfikacja ryzyka modeli","o":"bufory, wrażliwość założeń","k":"V","s":"Szacunek, ile może kosztować błąd modelu: analiza wrażliwości założeń, porównanie z modelami alternatywnymi, bufory.","idea":"ryzyko modelu ≈ rozrzut wyników wiarygodnych wersji","use":"Rekomendacja W, Filar 2.","u":3,"reg":"","old":"","ot":"Scenariusz / ekspert","otc":"#a8443a","det":{"p":["Ryzyko modelu to ryzyko strat wynikających z decyzji opartych na modelu, który jest błędny albo źle użyty. Źródła są różne: błędne założenia, słabe dane, błędy implementacji, użycie modelu poza zakresem, do którego go zbudowano. Rekomendacja W KNF wymaga zarządzania nim w całym cyklu życia modeli.","Kwantyfikacja odpowiada na pytanie: o ile może się mylić wynik modelu. Praktyczne narzędzia to: analiza wrażliwości kluczowych założeń, porównanie z modelami alternatywnymi (benchmarkami), przedziały ufności parametrów (np. z bootstrapu), analiza wyników walidacji (ile testów nie przechodzi), a także scenariusze błędu implementacji. Wynik przekłada się na bufory – marże ostrożności w parametrach (MoC w IRB) – albo na kapitał w Filarze 2.","Ważne jest też ryzyko agregatu: wiele modeli o średniej jakości użytych łańcuchowo (PD → ECL → plan kapitałowy) może dać duży łączny błąd."],"ex":["Dwie wiarygodne wersje modelu",["Model LGD w dwóch wersjach (różne okno danych): 25% i 30%.","Różnica w ECL portfela: 20%, tj. 40 mln zł.","Bank przyjmuje wersję 25% z marżą ostrożności +2 pp → LGD 27%.","Pozostałą niepewność obejmuje bufor w Filarze 2."]]},"par":[["b","bufor na ryzyko modelu","Z rozrzutu wyników wiarygodnych wersji modelu i analizy wrażliwości."]]},{"id":"tier","d":"M","g":"","n":"Inwentarz i istotność modeli","o":"Rekomendacja W, tiering","k":"V","s":"Rejestr wszystkich modeli i ich klasyfikacja według istotności (wpływ, złożoność, niepewność), która wyznacza zakres i częstotliwość walidacji.","idea":"istotność = f(wpływ na wynik i kapitał, złożoność, niepewność)","use":"Planowanie walidacji, ład modelowy.","u":5,"reg":"Rekomendacja W KNF (zarządzanie ryzykiem modeli)","old":"","ot":"Klasyfikacja","otc":"#b08a1e","det":{"p":["Zarządzanie ryzykiem modeli zaczyna się od pytania: jakie modele w ogóle mamy. Rekomendacja W wymaga, by bank prowadził rejestr (inwentarz) wszystkich modeli – z właścicielem, przeznaczeniem, wersją, datą ostatniej walidacji, ustaleniami i ich stanem realizacji. Modelem jest nie tylko PD czy VaR, ale też arkusz kalkulacyjny, który wpływa na decyzje.","Każdy model dostaje klasę istotności. Ocenia się zwykle trzy wymiary: wpływ (na wynik, kapitał, decyzje biznesowe i klientów), złożoność (metoda, liczba założeń, zależności od innych modeli) i niepewność (jakość danych, wyniki walidacji, historia problemów). Z połączenia wymiarów wynika np. klasa wysoka, średnia lub niska.","Klasa istotności decyduje o tym, jak głęboka i jak częsta jest walidacja, kto zatwierdza model i zmiany, jak szczegółowa ma być dokumentacja i monitoring. Dzięki temu zasoby walidacji trafiają tam, gdzie błąd modelu kosztowałby najwięcej."],"ex":["Dwa modele, dwie klasy",["Model PD dla hipotek: wpływ wysoki (ECL, kapitał IRB), złożoność średnia, niepewność średnia → klasa wysoka.","Walidacja pełna co roku, zatwierdza komitet, monitoring kwartalny.","Model prognozy liczby wniosków w oddziałach: wpływ niski, złożoność niska → klasa niska.","Przegląd uproszczony co 3 lata, zatwierdza właściciel modelu."]]},"par":[["k","klasa istotności","Z ocen wpływu, złożoności i niepewności – reguły i ocena ekspercka."]]}],"KL":{"EL":"Strata oczekiwana","UL":"Strata nieoczekiwana / kapitał","W":"Wycena i ekspozycja","B":"Zachowania klientów","P":"Płynność i finansowanie","S":"Scenariusze i stres","V":"Walidacja i ryzyko modeli"}};
